import{f as o,o as a,c,a2 as t}from"./chunks/framework.Cd9rfTEn.js";const g=JSON.parse('{"title":"04 — Mora, intereses y corte","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/reglas-negocio/04-mora-intereses-y-corte.md","filePath":"relevamiento/reglas-negocio/04-mora-intereses-y-corte.md","lastUpdated":null}'),d={name:"relevamiento/reglas-negocio/04-mora-intereses-y-corte.md"};function n(r,e,s,i,l,u){return a(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="_04-—-mora-intereses-y-corte" tabindex="-1">04 — Mora, intereses y corte <a class="header-anchor" href="#_04-—-mora-intereses-y-corte" aria-label="Permalink to &quot;04 — Mora, intereses y corte&quot;">​</a></h1><p>Reglas de Procoop sobre intereses por pago fuera de término, gestión de mora (instancias y notificaciones), corte y reconexión de servicios, planes de pago y prescripción de deuda. Salen del código descompilado de Procoop 10.4.6.722.</p><p>Las citas usan el formato <code>Clase.Método</code> y <code>archivo:línea</code>. Las rutas son relativas a <code>binarios/decompilado/ReglasNegocio/</code>. Los parámetros se identifican por número (<code>Nucleo.Busca_V2_*(N)</code>); sus descripciones están en <code>CapaNucleo/clsVariables.cs</code>. El código es de terceros: se describe en prosa y con pseudocódigo breve, sin copiar fuentes.</p><h2 id="_1-mapa-general" tabindex="-1">1. Mapa general <a class="header-anchor" href="#_1-mapa-general" aria-label="Permalink to &quot;1. Mapa general&quot;">​</a></h2><p>Procoop cobra intereses en tres momentos distintos, y cada uno tiene su propio motor de cálculo:</p><table tabindex="0"><thead><tr><th>Momento</th><th>Qué se calcula</th><th>Dónde</th></tr></thead><tbody><tr><td>Al <strong>emitir</strong> la factura</td><td>Importes de los vencimientos 2, 3 y 4 (<code>TOTAL2..TOTAL4</code>): &quot;recargo entre vencimientos&quot;</td><td><code>clsComprobanteFactura.Get_ImporteFactura</code> (<code>ReglasNegocio.Facturacion/clsComprobanteFactura.cs:1771</code>)</td></tr><tr><td>Al <strong>cobrar</strong> o consultar deuda (caja, entes, portal)</td><td>Recargo por mora pasado el último vencimiento, más el recargo entre vencimientos ya devengado</td><td><code>clsCobranzas.Get_Recargo</code> (<code>ReglasNegocio.Cobranzas/clsCobranzas.cs:1814</code>)</td></tr><tr><td>En un <strong>proceso masivo</strong></td><td>&quot;Intereses a facturar por deuda vencida impaga&quot; (o ya paga fuera de término), que se cargan a la próxima factura</td><td><code>clsFacturarIntereses</code> (<code>ReglasNegocio.Facturacion/clsFacturarIntereses.cs</code>)</td></tr></tbody></table><p>La gestión de mora funciona aparte del cálculo de intereses. Es un circuito de <strong>notificaciones por instancias</strong> (tablas <code>NOTIFICA</code> y <code>COMPNOTI</code>):</p><ol><li>Se seleccionan candidatos desde &quot;Circulares&quot; (<code>clsCirculares</code>).</li><li>Cada notificación avanza de instancia en instancia (<code>clsGestionMora</code>).</li><li>La última etapa es el &quot;tratamiento de morosos&quot;: órdenes de trabajo (OT) de desconexión, cambio de estado o cambio de categoría.</li><li>Si la deuda se paga, la reconexión puede ser automática (<code>clsRegistracionCobranza</code>).</li></ol><h2 id="_2-modelo-de-datos-involucrado" tabindex="-1">2. Modelo de datos involucrado <a class="header-anchor" href="#_2-modelo-de-datos-involucrado" aria-label="Permalink to &quot;2. Modelo de datos involucrado&quot;">​</a></h2><p>Tablas según <code>binarios/CapaDatos-tablas.md</code> y su uso en el código:</p><table tabindex="0"><thead><tr><th>Tabla</th><th>Rol</th></tr></thead><tbody><tr><td><code>FACTURAS</code></td><td>Tiene <code>VTO1..VTO4</code> y <code>TOTAL1..TOTAL4</code> (importe a pagar en cada vencimiento), <code>SALDO</code>, <code>FECHASALDO</code> (fecha del último pago), <code>PAGA</code> (<code>&quot;P&quot;</code> = paga), <code>NOINTERES</code> (no calcular interés), <code>ID_BLO</code> (causa de bloqueo), <code>CLASE</code> (1 = cuota de financiación), <code>NRO_REF</code> (convenio), <code>COD_FAC</code> (se usa como marca <code>&#39;Punitorio&#39;</code>).</td></tr><tr><td><code>MORATAS</code> (+ <code>MORATAS_CATSER</code>)</td><td>Tabla de tasas de mora por rango de fechas: <code>FEDESDE</code>, <code>FEHASTA</code>, <code>TASA_CASO</code> (% diario), <code>TIPO</code> (tipo de factura; vacío = todos), servicio y, opcionalmente, categorías de servicio.</td></tr><tr><td><code>TABMORA</code> → <code>INDICESMORA</code></td><td>Tabla de índices (fecha → valor) para calcular la mora &quot;por índices&quot;. <code>TABMORA.TIPO_FAC</code> restringe los tipos de factura alcanzados.</td></tr><tr><td><code>TRAMASREC</code></td><td>Tramas de recargo para los vencimientos 2 a 4, por tipo de factura y rango de importe (<code>IMP_DES</code>, <code>IMP_HAS</code>, <code>VAL_TRAMA</code>, <code>TIPOVALOR</code>).</td></tr><tr><td><code>CONCEPTOS_INT</code></td><td>Conceptos e impuestos que forman la base del interés (por servicio). <code>TIPO</code> distingue el uso (ver §3.2 y §4.2).</td></tr><tr><td><code>DESCUENTO_CAJA</code></td><td>Descuento por pronto pago (tasa negativa) por tipo de factura y rango de días desde la emisión.</td></tr><tr><td><code>EXC_MORA</code></td><td>Excepciones de mora por cuenta: <code>VIGENCIA</code> (<code>&#39;SI&#39;</code>), <code>RECLAMAR</code>, <code>RETENER</code>, <code>FECHA</code> (hasta cuándo rige), <code>FEC_DEUDA</code> (deuda anterior a esa fecha), <code>FEC_VIG</code> (fecha de cancelación), <code>MOTIVO</code>, <code>USU_REG</code>, <code>USU_VIG</code>, <code>FEC_REG</code>.</td></tr><tr><td><code>INSTANCI</code></td><td>Catálogo de instancias de mora (CANDIDATOS, 1er aviso, 2do aviso, corte, etc.). La instancia de candidatos es el parámetro 2202.</td></tr><tr><td><code>NOTIFICA</code></td><td>Una notificación por cuenta, lote e instancia: <code>COD_INS</code>, <code>LOTE</code>, <code>FECHA</code>, <code>VTO_CIR</code> (vencimiento de la circular), <code>RECIBIO</code>/<code>FEC_REC</code>, <code>PROMESA</code>, <code>RESUELTA</code>, <code>FEC_RES</code>/<code>USU_RES</code>, <code>COD_CAU</code> (causa de baja), <code>CALIFICA</code>, <code>DEUDA</code>, <code>DEUDA_AC</code>, <code>COD_PLA</code> (plantilla), <code>OBSERVA2</code> (bitácora).</td></tr><tr><td><code>COMPNOTI</code></td><td>Comprobantes incluidos en cada notificación, con el saldo al momento de notificar.</td></tr><tr><td><code>CAUBLOQ</code> / <code>HISBLOQ</code></td><td>Causas de bloqueo de comprobantes e historial de bloqueos.</td></tr><tr><td><code>CONEXION</code></td><td>Conceptos a cobrar por evento. <code>TIPO_CON = 4</code> es &quot;Reconexión de servicio&quot; (enum <code>TipoConceptoCobrar</code>, <code>ReglasNegocio.Titulares/TipoConceptoCobrar.cs</code>).</td></tr><tr><td><code>PLAN_CUO</code>, <code>TIP_FIN</code>, <code>REC_CON</code>, <code>IT_RECCO</code></td><td>Planes de pago, tipos de financiación, cabecera del convenio y comprobantes refinanciados.</td></tr><tr><td><code>DEUDAVTA</code></td><td>Cuotas pendientes de facturar de un comprobante de venta (<code>COMP_VEN</code>). <code>TPCUOTA = 1</code> son intereses diferidos.</td></tr><tr><td><code>INFLACIO</code> (vía <code>TABINFL</code>)</td><td>Índices de ajuste de cuotas de planes.</td></tr></tbody></table><h2 id="_3-recargo-entre-vencimientos-al-emitir-la-factura" tabindex="-1">3. Recargo entre vencimientos al emitir la factura <a class="header-anchor" href="#_3-recargo-entre-vencimientos-al-emitir-la-factura" aria-label="Permalink to &quot;3. Recargo entre vencimientos al emitir la factura&quot;">​</a></h2><h3 id="_3-1-calculo-de-total2-total4" tabindex="-1">3.1 Cálculo de <code>TOTAL2..TOTAL4</code> <a class="header-anchor" href="#_3-1-calculo-de-total2-total4" aria-label="Permalink to &quot;3.1 Cálculo de `TOTAL2..TOTAL4`&quot;">​</a></h3><p><code>clsComprobanteFactura.Get_ImporteFactura</code> (<code>clsComprobanteFactura.cs:1771-1793</code>) calcula el importe de cada vencimiento posterior al primero. La variante sale del parámetro <strong>74</strong> (enum <code>Facturacion_TipoInteresFactura</code>); el valor de recargo suele ser el parámetro <strong>578</strong>.</p><table tabindex="0"><thead><tr><th>Valor del 74</th><th>Regla</th><th>Archivo:línea</th></tr></thead><tbody><tr><td>Ninguno</td><td><code>TOTALk = TOTAL1</code></td><td>—</td></tr><tr><td>Variable_Porcentaje</td><td><code>TOTALk = TOTAL1 + TOTAL1 × 578% × días(VTOk − VTO1)</code>, más IVA del interés</td><td><code>:1795</code></td></tr><tr><td>Fijo_Porcentaje</td><td>Porcentaje fijo <strong>en cascada</strong>: VTO2 = TOTAL1 × (1+p); VTO3 se calcula sobre VTO2, y así sucesivamente</td><td><code>:1803</code></td></tr><tr><td>Fijo_Pesos</td><td>Suma <code>578 × 1</code>, <code>× 2</code> o <code>× 3</code> pesos según el vencimiento, <strong>sin IVA</strong></td><td><code>:1826</code></td></tr><tr><td>Tramas_Importe</td><td>Busca en <code>TRAMASREC</code> la fila del tipo de factura (o con <code>TIPO</code> vacío, con menor prioridad) cuyo rango <code>IMP_DES..IMP_HAS</code> contiene el importe y aplica <code>VAL_TRAMA % × días(VTOk − VTO1)</code>. Si <code>TIPOVALOR = 1</code>, días = 1 (valor fijo). Para VTO3 y VTO4 el cálculo es <strong>en cascada</strong>: primero arma un importe intermedio con interés e IVA y vuelve a aplicar la trama sobre ese importe (ver §3.3).</td><td><code>:1839-1868</code></td></tr><tr><td>Trama_Vencimiento</td><td><code>TRAMASREC</code> con <code>IMP_DES = IMP_HAS = 1, 2 o 3</code> identifica la fila de cada vencimiento. Si no existe, usa la primera trama del tipo (o general). Sin cascada.</td><td><code>:1871-1916</code></td></tr></tbody></table><p><code>CalcularIVA_Interes</code> (<code>:1918-1927</code>) aplica al interés la alícuota del concepto de interés (parámetro <strong>606</strong>), según la situación de IVA del titular, más la percepción si corresponde.</p><p>Otros parámetros de emisión: <strong>2109</strong> (intereses en los vencimientos 2 y 3), <strong>2283</strong> (recargo por cambio de trama) y <strong>733</strong> (factura en cuotas con interés).</p><h3 id="_3-2-que-pasa-con-ese-recargo-al-cobrar" tabindex="-1">3.2 Qué pasa con ese recargo al cobrar <a class="header-anchor" href="#_3-2-que-pasa-con-ese-recargo-al-cobrar" aria-label="Permalink to &quot;3.2 Qué pasa con ese recargo al cobrar&quot;">​</a></h3><p>Cuando se cobra antes del VTO4, el recargo es la diferencia entre el <code>TOTALk</code> del vencimiento vigente y <code>TOTAL1</code> (ver §4.3). Ese importe ya está &quot;embebido&quot; en la factura con IVA incluido, y se lo trata así: se usa <code>Calcular_TasasIVA_Total</code>, que separa el IVA del total, en lugar de sumarlo.</p><h3 id="_3-3-detalle-de-cada-variante-segunda-pasada" tabindex="-1">3.3 Detalle de cada variante (segunda pasada) <a class="header-anchor" href="#_3-3-detalle-de-cada-variante-segunda-pasada" aria-label="Permalink to &quot;3.3 Detalle de cada variante (segunda pasada)&quot;">​</a></h3><p>Revisión método por método de <code>clsComprobanteFactura.cs:1771-1927</code>:</p><ul><li><strong><code>CalcularTotalFactura_VariablePorcentaje</code></strong> (<code>:1795-1801</code>): días = <code>(VTOk − VTO1)</code> en días enteros; interés = <code>importe × 578 / 100 × días</code>; se le suma el IVA del interés. Interés simple sobre el <code>TOTAL1</code>.</li><li><strong><code>CalcularTotalFactura_FijoPorcentaje</code></strong> (<code>:1803-1824</code>): VTO2 = <code>importe + IVA(importe × 578%)</code>; VTO3 aplica el mismo porcentaje sobre el total del VTO2 y VTO4 sobre el del VTO3. Es interés <strong>compuesto por escalón</strong>, y cada escalón incluye el IVA del escalón anterior en la base.</li><li><strong><code>CalcularTotalFactura_FijoPesos</code></strong> (<code>:1826-1837</code>): suma <code>578 × 0/1/2/3</code> pesos para VTO1/2/3/4 (cualquier otro vencimiento cae en ×3). No pasa por <code>CalcularIVA_Interes</code>: el recargo en pesos no lleva IVA.</li><li><strong><code>CalcularTotalFactura_TramaImporte</code></strong> (<code>:1839-1868</code>): la fila de <code>TRAMASREC</code> se elige por tipo de factura (<code>TIPO</code> exacto antes que <code>TIPO = &#39;&#39;</code>, luego <code>COD_TRM</code>) y por el rango de importe del <code>TOTAL1</code>. Para VTO3 y VTO4 el código arma primero un importe intermedio <code>importe + IVA(importe × trama × días)</code> y aplica de nuevo la trama sobre él; en VTO4 vuelve a partir de <code>importe</code> pero con el intermedio como base. Los días usados son siempre <code>VTOk − VTO1</code>, de modo que en VTO3/VTO4 se cobra interés sobre interés y con días acumulados. <strong>[VERIFICAR]</strong> con facturas reales si este doble cómputo es intencional: podría ser un error del código original.</li><li><strong><code>CalcularTotalFactura_TramaVencimiento</code></strong> (<code>:1871-1916</code>): la fila con <code>IMP_DES = IMP_HAS = 1/2/3</code> corresponde a VTO2/VTO3/VTO4. Si falta, toma la primera trama del tipo. Interés = <code>importe × trama × días / 100</code> (o <code>× 1</code> si <code>TIPOVALOR = 1</code>) más IVA, sin cascada.</li><li><strong><code>CalcularIVA_Interes</code></strong> (<code>:1918-1927</code>): toma el concepto del parámetro <strong>606</strong> (&quot;Concepto para interés por mora&quot;). Si el concepto existe y la factura tiene situación de IVA, devuelve <code>importe + ImporteIva</code> (<code>Impuestos.Calcular_TasasIVA</code> con la percepción del producto, <code>Pre_Per</code>). Si el concepto no está configurado, el recargo queda <strong>sin IVA</strong> sin avisar.</li><li><strong><code>ExisteMoratas(cod_tip, out des_mot)</code></strong> (<code>:492-508</code>): devuelve <code>true</code> si existe alguna fila de <code>MORATAS</code> con <code>TIPO</code> igual al tipo de factura (sin distinguir mayúsculas) y <code>DES_MOT</code> no vacío, y devuelve esa descripción. No mira la vigencia (<code>FEDESDE</code>/<code>FEHASTA</code>) ni las tasas generales (<code>TIPO</code> vacío), así que solo informa si hay tasas <strong>específicas</strong> del tipo.</li></ul><h2 id="_4-recargo-por-mora-al-cobrar-motor-principal" tabindex="-1">4. Recargo por mora al cobrar (motor principal) <a class="header-anchor" href="#_4-recargo-por-mora-al-cobrar-motor-principal" aria-label="Permalink to &quot;4. Recargo por mora al cobrar (motor principal)&quot;">​</a></h2><h3 id="_4-1-variables-de-calculo" tabindex="-1">4.1 Variables de cálculo <a class="header-anchor" href="#_4-1-variables-de-calculo" aria-label="Permalink to &quot;4.1 Variables de cálculo&quot;">​</a></h3><p><code>clsCobranzas.VariablesConsulta</code> (<code>clsCobranzas.cs:399-524</code>) carga una sola vez:</p><table tabindex="0"><thead><tr><th>Parámetro / fuente</th><th>Uso</th></tr></thead><tbody><tr><td>Tabla <code>MORATAS</code></td><td>Tasas por rango de fechas</td></tr><tr><td>Tabla <code>DESCUENTO_CAJA</code></td><td>Descuentos por pronto pago</td></tr><tr><td><code>Nucleo.CalculoRecargoMoraPorIndices()</code></td><td>Vale <code>true</code> si <code>INDICESMORA</code> tiene filas (<code>CapaNucleo/Nucleo.cs:3028-3043, 4406</code>)</td></tr><tr><td><code>GetTipoFacturaRecargoMoraIndices()</code></td><td><code>TABMORA.TIPO_FAC</code> (<code>Nucleo.cs:3045-3064, 4411</code>)</td></tr><tr><td>600</td><td>Recargo diario fijo (% diario). También puede llegar como argumento desde el ente recaudador.</td></tr><tr><td>606 / 307 / <code>TIPO_FAC.COD_CON</code></td><td>Concepto de interés por mora: general / en modo &quot;Financiación de deuda&quot; / por tipo de factura</td></tr><tr><td><code>TIPO_FAC.COD_CON2</code> / 2080</td><td>Concepto de interés entre vencimientos</td></tr><tr><td>621</td><td>&quot;Recargo desde tercer vencimiento&quot;: el interés corre desde el último vencimiento y no desde el VTO1</td></tr><tr><td>608</td><td>Redondear el recargo total a 1 decimal</td></tr><tr><td>609</td><td>Importe mínimo del recargo por mora</td></tr><tr><td>372</td><td>Gastos administrativos fijos por factura en mora</td></tr><tr><td>625</td><td>Calcular intereses sobre créditos (notas de crédito)</td></tr><tr><td>299 / 1002</td><td>Jubilados: quitar el recargo del VTO2 / no cobrarles recargo</td></tr><tr><td>1011</td><td>Modo de diferimiento: 1 NoDiferir, 2 DiferirInteresMora, 3 DiferirTodo (0 se toma como 1)</td></tr><tr><td>2356</td><td>Discriminar el interés entre vencimientos del interés por mora</td></tr><tr><td>2363</td><td>Recargo entre vencimientos proporcional al saldo</td></tr><tr><td>2826</td><td>IIBB sobre el interés entre vencimientos</td></tr><tr><td>2300</td><td>Códigos de impuesto (separados por coma) que se excluyen de la base</td></tr><tr><td>3135</td><td>Respetar <code>SUMSOC.SIN_RECARGO</code> (cuenta sin recargo)</td></tr><tr><td>3167</td><td>La base del interés es la suma de ítems de conceptos configurados en <code>CONCEPTOS_INT</code> (<code>TIPO &gt; 0</code>)</td></tr><tr><td>2086</td><td>Situación de IVA por defecto</td></tr><tr><td>Ente recaudador</td><td><code>RECARGO3VTO</code>, <code>DIFERIR</code>, <code>COBVTO1</code> sobrescriben el comportamiento para cobros por entes</td></tr><tr><td>719 / 718</td><td>Comisión de cobranza remota (concepto e importe)</td></tr></tbody></table><p>Además, el parámetro <strong>2385</strong> excluye de caja y consulta los comprobantes con VTO2 anterior a hoy menos N días, salvo que el usuario tenga el permiso <code>ExcluirComprobVto2</code> (<code>clsCobranzas.InfoFiltros</code>, <code>:71-86</code>).</p><h3 id="_4-2-habilitacion-del-interes-por-factura" tabindex="-1">4.2 Habilitación del interés por factura <a class="header-anchor" href="#_4-2-habilitacion-del-interes-por-factura" aria-label="Permalink to &quot;4.2 Habilitación del interés por factura&quot;">​</a></h3><p><code>Get_Recargo(Datos_Factura…)</code> (<code>clsCobranzas.cs:1701-1761</code>) define <code>CalcularInteres = false</code> en estos casos:</p><ul><li>el titular es jubilado (<code>Tipo_Ocupacion = 2</code>) y el parámetro 1002 dice no cobrarle;</li><li>la factura tiene <code>NOINTERES</code>;</li><li>la cuenta tiene <code>SIN_RECARGO</code> y el parámetro 3135 está activo.</li></ul><p><code>Get_Datos_Factura</code> (<code>:2971-3183</code>) arma la base. Calcula el importe de los impuestos excluidos (2300) y el importe de recargo por conceptos (3167). En las cuotas de financiación separa los ítems por <code>SUBTIPO</code>: 24 capital, 21 interés actual, 22 interés anterior y 23 interés por mora. En pagos online (Pagos360) toma la fecha de cobro y un posible <code>InteresFijo</code>.</p><p>Hay una versión equivalente para cuotas de talón (<code>:1763-1812</code>).</p><h3 id="_4-3-algoritmo-get-recargo-infointeres-variables-clscobranzas-cs-1814-2102" tabindex="-1">4.3 Algoritmo <code>Get_Recargo(InfoInteres, variables)</code> (<code>clsCobranzas.cs:1814-2102</code>) <a class="header-anchor" href="#_4-3-algoritmo-get-recargo-infointeres-variables-clscobranzas-cs-1814-2102" aria-label="Permalink to &quot;4.3 Algoritmo `Get_Recargo(InfoInteres, variables)` (`clsCobranzas.cs:1814-2102`)&quot;">​</a></h3><p>Pseudocódigo resumido:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>si !CalcularInteres o (esCrédito y !param625) o saldo == 0 → recargo 0</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>si FechaConsulta &lt; VTO1 y hay DESCUENTO_CAJA para el tipo (solo socios):</span></span>\n<span class="line"><span>    tasa negativa según días desde la emisión (DIA_DESDE..DIA_HASTA)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>si FechaConsulta &lt;= VTO4:                        // todavía en vencimientos</span></span>\n<span class="line"><span>    entreVto = TOTAL_k(vencimiento vigente) − TOTAL1 − lo ya absorbido por pagos (según FECHASALDO)</span></span>\n<span class="line"><span>    si jubilado y param299: restar (TOTAL2 − TOTAL1)</span></span>\n<span class="line"><span>    si param2363: entreVto × SALDO / TOTAL1</span></span>\n<span class="line"><span>sino:                                            // mora</span></span>\n<span class="line"><span>    fechaBase = sin pagos → VTO1 (o VTO4 si 621); con pagos parciales → vencimiento que corresponde a FECHASALDO</span></span>\n<span class="line"><span>    base      = sin pagos → TOTAL1 (o TOTAL4 si 621) − impuestos excluidos (2300); con pagos → SALDO</span></span>\n<span class="line"><span>                si 3167 → base = importe de conceptos de CONCEPTOS_INT</span></span>\n<span class="line"><span>    días      = FechaConsulta − fechaBase</span></span>\n<span class="line"><span>    tasa por prioridad:</span></span>\n<span class="line"><span>      a) param600 (o recargo diario recibido) ≠ 0 → base × tasa × días / 100</span></span>\n<span class="line"><span>      b) INDICESMORA con datos y tipo de factura alcanzado:</span></span>\n<span class="line"><span>           factor = índice(≤ FechaConsulta) / índice(≥ fechaBase) − 1 ;  interés = base × factor</span></span>\n<span class="line"><span>      c) MORATAS: por cada tramo FEDESDE..FEHASTA que se solapa con [fechaBase, FechaConsulta],</span></span>\n<span class="line"><span>           filtrando por TIPO de factura (o vacío) y categoría de servicio (MORATAS_CATSER tiene prioridad),</span></span>\n<span class="line"><span>           interés += base × TASA_CASO × díasSolapados / 100</span></span>\n<span class="line"><span>    IVA y percepción con la alícuota del concepto de interés; IIBB con Calcular_IBR</span></span>\n<span class="line"><span>    si 2356 o 621: separar entreVto = (TOTAL4 − TOTAL1 − absorbido) × SALDO / TOTAL1;</span></span>\n<span class="line"><span>                   si !621 descontarlo del recargo por mora</span></span>\n<span class="line"><span>si recargoMora &lt; mínimo(609) → recargoMora = 0</span></span>\n<span class="line"><span>si pasó VTO4 → sumar gastos administrativos (372)</span></span>\n<span class="line"><span>Recargo_Total = mora + entreVto + gastos ; si 608 → redondear a 1 decimal</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><p>Detalles:</p><ul><li><strong>Índices</strong>: <code>CalcularRecargoMoraPorIndice</code> (<code>:2104-2138</code>) y <code>GetIndiceMora</code> (<code>:2154-2167</code>). Para la fecha de consulta busca el índice &quot;anterior o igual&quot;; para la fecha base, el &quot;siguiente o igual&quot;. Convierte el resultado en una tasa diaria equivalente para mostrarla en el detalle.</li><li><strong>MORATAS por tramos</strong>: <code>:1975-2042</code>. Si una categoría de servicio coincide, se usan solo las tasas de esa categoría; si no, las tasas sin categoría. Para cada tramo se calculan los días dentro de él.</li><li><strong>Separación de componentes</strong>: <code>InfoRecargo</code> (<code>:89-174</code>) separa <code>RecargoMora</code>, <code>RecargoEntreVencimiento</code> y <code>GastosAdministrativos</code>, cada uno con Neto, IVA1, IVA2, Percepción e IBR (<code>InfoImporte</code>, <code>:176-320</code>).</li></ul><p>Conclusión: el interés es siempre <strong>simple y diario</strong> sobre la base. No se capitaliza; la única excepción es el método de índices, donde el cociente de índices ya trae la composición del índice.</p><h3 id="_4-4-diferimiento-del-interes" tabindex="-1">4.4 Diferimiento del interés <a class="header-anchor" href="#_4-4-diferimiento-del-interes" aria-label="Permalink to &quot;4.4 Diferimiento del interés&quot;">​</a></h3><p><code>InfoCobranza</code> (<code>clsCobranzas.cs:671</code> en adelante) calcula tres importes: <code>Total</code> (<code>:615-630</code>, <code>:955</code>), <code>ImporteaFacturar</code> (<code>:842-860</code>) e <code>ImporteNetoaDiferir</code> (<code>:862-872</code>). Enum <code>DiferirInteres</code> en <code>:2510-2518</code>.</p><table tabindex="0"><thead><tr><th>Modo (1011 o ente)</th><th>Qué paga el titular en caja</th><th>Qué queda diferido</th></tr></thead><tbody><tr><td>NoDiferir</td><td>Factura + mora + entre vencimientos</td><td>Nada</td></tr><tr><td>DiferirInteresMora</td><td>Factura + entre vencimientos</td><td>El interés por mora</td></tr><tr><td>DiferirTodo</td><td>Solo la factura</td><td>Todo el interés</td></tr></tbody></table><p>Registro (<code>clsRegistracionCobranza.RegistrarIntereses</code>, <code>ReglasNegocio.Cobranzas/clsRegistracionCobranza.cs:655-955</code>):</p><ul><li><strong>Lo que se cobra en el acto</strong> se factura en el momento con un comprobante nuevo por cuenta, situación de IVA, situación de IIBB y, si el parámetro <strong>1056</strong> está activo, por tipo de factura. <ul><li>Ítems: &quot;Intereses - {comprobante}&quot; (concepto 606 o <code>COD_CON</code> del tipo de factura) y &quot;Intereses en Vto - {comprobante}&quot; (concepto 2080 o <code>COD_CON2</code>), ambos con subtipo <code>Intereses_cobrados_en_caja</code>.</li><li>Si aplica descuento de caja, ítem &quot;Descuento x %&quot;.</li><li>El tipo de comprobante lo decide el parámetro <strong>273</strong>: factura o <strong>nota de débito</strong> (<code>NuevaFactura</code>, <code>:1305-1333</code>). Si el total da negativo, se invierte a crédito.</li><li>Ese comprobante queda relacionado con las facturas pagadas.</li><li>Las cuotas de financiación (<code>CLASE = 1</code>) copian sus ítems de interés (subtipos 21, 22 y 23) y se relacionan con el convenio.</li></ul></li><li><strong>Lo diferido</strong> genera un comprobante de venta (<code>COMP_VEN</code>) con la operación <code>Intereses_Diferidos_Debito</code> (o <code>_Credito</code> si el neto es negativo) y una cuota <code>TPCUOTA = 1</code> en <code>DEUDAVTA</code> (<code>:834-955</code>). <ul><li>La facturación masiva levanta esas cuotas en la <strong>próxima factura</strong> cuando se procesa con la opción <code>InteresesDiferidos</code> (<code>ReglasNegocio.Facturacion/clsFacturacionMasiva.cs:1814-1826</code>).</li><li>El parámetro <strong>2828</strong> asocia la cuota al servicio de la factura original.</li></ul></li><li><strong>Recargos por medio de pago</strong> (cheque de terceros, transferencia, tarjeta) usan los conceptos <strong>487</strong>, <strong>2070</strong> y <strong>2069</strong> (<code>:1215-1303</code>). El parámetro <strong>486</strong> es la tasa diaria por valores a fecha.</li></ul><h3 id="_4-5-validaciones-de-carga-de-tasas-y-descuentos-segunda-pasada" tabindex="-1">4.5 Validaciones de carga de tasas y descuentos (segunda pasada) <a class="header-anchor" href="#_4-5-validaciones-de-carga-de-tasas-y-descuentos-segunda-pasada" aria-label="Permalink to &quot;4.5 Validaciones de carga de tasas y descuentos (segunda pasada)&quot;">​</a></h3><p>Las pantallas de alta de <code>MORATAS</code> y <code>DESCUENTO_CAJA</code> no están en los ensamblados descompilados (ver §14). Sí están los métodos de <code>clsCobranzas</code> que esas pantallas usan para validar:</p><ul><li><strong><code>Hay_Moratas(tipo, desde, hasta, cod_mot, servicio, categorías)</code></strong> (<code>ReglasNegocio.Cobranzas/clsCobranzas.cs:2785-2799</code>): busca otras tasas (<code>COD_MOT</code> distinto) del mismo <code>TIPO</code> de factura y servicio cuyo rango de fechas se superponga con <code>[desde, hasta]</code>. Solo informa conflicto si alguna de las categorías nuevas ya está asignada (<code>MORATAS_CATSER</code>) a una de esas tasas superpuestas. Consecuencia: <strong>dos tasas generales (sin categorías) superpuestas para el mismo tipo y servicio no se detectan como conflicto</strong>. En el cálculo (§4.3), las dos sumarían interés en el tramo común. <strong>[VERIFICAR]</strong> si la pantalla tiene otra validación adicional.</li><li><strong><code>GuardarCategoriasMorata</code></strong> (<code>:2801-2822</code>): reemplaza todas las categorías de una tasa (borra y vuelve a insertar). <code>TieneCategoriasAsignadas</code> (<code>:2824</code>) informa si la tasa es específica por categoría.</li><li><strong><code>Exist_Descuento(tipo, díaDesde, díaHasta, ignorar)</code></strong> (<code>:4448-4452</code>): no se permiten dos tramos de <code>DESCUENTO_CAJA</code> del mismo tipo de factura con rangos de días superpuestos.</li><li><strong><code>Get_MaxDescuentoCaja(tipo, ignorar)</code></strong> (<code>:4454-4459</code>): el porcentaje máximo que se puede cargar en un tramo es <code>100 − suma de los demás tramos del tipo</code>. Es decir, la suma de los descuentos de todos los tramos de un tipo no puede superar el 100 %. Es una regla de carga y no tiene sentido financiero, porque los tramos no se acumulan al cobrar.</li><li><code>Get_DescuentosCajaDataSource</code> (<code>:4431</code>): lista de tramos ordenada por <code>DIA_DESDE</code>, sin regla.</li></ul><h2 id="_5-proceso-masivo-intereses-a-facturar-clsfacturarintereses" tabindex="-1">5. Proceso masivo &quot;Intereses a facturar&quot; (<code>clsFacturarIntereses</code>) <a class="header-anchor" href="#_5-proceso-masivo-intereses-a-facturar-clsfacturarintereses" aria-label="Permalink to &quot;5. Proceso masivo &quot;Intereses a facturar&quot; (`clsFacturarIntereses`)&quot;">​</a></h2><h3 id="_5-1-filtros-y-variantes" tabindex="-1">5.1 Filtros y variantes <a class="header-anchor" href="#_5-1-filtros-y-variantes" aria-label="Permalink to &quot;5.1 Filtros y variantes&quot;">​</a></h3><p><code>Filtros</code> (<code>clsFacturarIntereses.cs:17-53</code>): tipo de factura, rango de fechas, cuenta, titular, grupo (incluir o excluir), <code>InteresDiario</code> (% diario), solo servicios conectados, procesar pagos entre fechas, <code>NoCalcularInteresAnterior</code>, concepto de interés, servicio, <code>FacturasImpagas</code> y <code>CalcularInteresesSoloSobreCargos</code>.</p><p><code>Get_Comprobantes</code> (<code>:230-243</code>) elige el algoritmo según el parámetro <strong>2292</strong> (&quot;Tipo de interés para facturas impagas&quot;):</p><table tabindex="0"><thead><tr><th>2292</th><th>Variante</th><th>Método</th></tr></thead><tbody><tr><td>1</td><td>Estándar</td><td><code>Get_ComprobanteIteres</code> sin cheques diferidos → <code>Get_InteresEstandar</code></td></tr><tr><td>2</td><td><strong>CAU</strong></td><td><code>Get_ComprobanteIteresCAU</code> (<code>:245-432</code>)</td></tr><tr><td>3</td><td>Cheques</td><td><code>Get_ComprobanteIteresCheques</code> (<code>:434-631</code>)</td></tr><tr><td>4 u otro</td><td><strong>AL</strong></td><td><code>Get_ComprobanteIteres</code> con cheques diferidos → <code>Get_InteresEstandarAL</code> (<code>:997-1214</code>)</td></tr></tbody></table><h3 id="_5-2-seleccion-de-facturas" tabindex="-1">5.2 Selección de facturas <a class="header-anchor" href="#_5-2-seleccion-de-facturas" aria-label="Permalink to &quot;5.2 Selección de facturas&quot;">​</a></h3><p><code>Get_Facturas</code> (<code>:1216-1258</code>) toma facturas de débito no anuladas (<code>ESTADO = &quot;&quot;</code>) y sin <code>NOINTERES</code>. Si no se pide <code>FacturasImpagas</code>, exige además saldo distinto de cero o una factura pagada con <code>FECHASALDO ≥ FechaDesde</code>, de modo que también se cobra interés por <strong>pagos fuera de término</strong>. Filtra por tipo, cuenta, titular, grupo (<code>AGR_SOC</code>) y servicios conectados (<code>clsSocios.Get_CondicionesConectadas</code>). El rango se aplica sobre VTO1 o sobre las fechas de pago.</p><h3 id="_5-3-variante-estandar-get-interesestandar-846-995" tabindex="-1">5.3 Variante estándar (<code>Get_InteresEstandar</code>, <code>:846-995</code>) <a class="header-anchor" href="#_5-3-variante-estandar-get-interesestandar-846-995" aria-label="Permalink to &quot;5.3 Variante estándar (`Get_InteresEstandar`, `:846-995`)&quot;">​</a></h3><p><code>Get_ComprobanteIteres</code> (<code>:633-844</code>) arma la historia de pagos de cada factura: la emisión cuenta como primer &quot;pago&quot; y los pagos se agrupan por día. Después calcula el interés de cada tramo entre pagos sucesivos con el saldo vigente en ese tramo:</p><ul><li><strong>Entre VTO1 y VTO4</strong>: suma los escalones <code>TOTAL2−TOTAL1</code>, <code>TOTAL3−TOTAL2</code> y <code>TOTAL4−TOTAL3</code> cuyos vencimientos caen dentro del tramo. Los trata con IVA incluido.</li><li><strong>Después de VTO4</strong>: <code>SALDO × días × InteresDiario / 100</code>, con IVA agregado.</li><li><strong>Cheques diferidos</strong>: la parte pagada con cheques posteriores al VTO4 genera interés hasta la fecha promedio de esos cheques (<code>:853-870</code>, <code>:916-952</code>).</li><li><strong><code>NoCalcularInteresAnterior</code></strong>: descuenta de la base la proporción <code>INTERES / TOTAL1</code>, donde <code>INTERES</code> es lo ya facturado con el concepto de interés en <code>ITEMSFAC</code>. Evita cobrar interés sobre interés.</li></ul><p>La variante <strong>AL</strong> es igual, con ajustes por pagos y cheques anteriores al rango y topes de proporción entre 0 y 100 %.</p><p>La variante <strong>Cheques</strong> calcula, por cada cheque (<code>VALORES.FEC_CHEQ</code>), interés desde <code>FechaDesde</code> hasta la fecha del cheque (tipo &quot;Cheque&quot;) y recalcula el saldo en cada tramo entre pagos.</p><h3 id="_5-4-variante-cau-245-432" tabindex="-1">5.4 Variante CAU (<code>:245-432</code>) <a class="header-anchor" href="#_5-4-variante-cau-245-432" aria-label="Permalink to &quot;5.4 Variante CAU (`:245-432`)&quot;">​</a></h3><ul><li>Con <code>FacturasImpagas</code>: <strong>punitorio</strong> = <code>SALDO × InteresDiario / 100</code>, <strong>una sola vez y sin multiplicar por días</strong>. Tipo &quot;Punitorio&quot;.</li><li>Sin esa opción: <ul><li><strong>Tramo VTO1 → VTO2</strong>: base = suma de ítems cuyos conceptos o impuestos están en <code>CONCEPTOS_INT</code> (<code>TIPO ≠ 1</code>), × parámetro 578 %.</li><li><strong>Tramo desde VTO2</strong>: <code>(TOTAL2 si no hubo pagos, o SALDO si los hubo) × días × InteresDiario / 100</code>.</li></ul></li><li><code>CalcularInteresesSoloSobreCargos</code> (<code>:248-249</code>, <code>:393-394</code>) limita el cálculo a comprobantes con <code>COD_COM</code> 96 o 97 que no estén marcados como &quot;Punitorio&quot;. En ese caso aplica un <strong>3 % fijo en el código</strong> sobre los cargos, proporcional al saldo.</li><li>El IVA se calcula con <code>Impuestos.Calcular_TasasIVA</code> según la alícuota de cada producto.</li></ul><h3 id="_5-5-generacion-de-los-comprobantes-de-interes" tabindex="-1">5.5 Generación de los comprobantes de interés <a class="header-anchor" href="#_5-5-generacion-de-los-comprobantes-de-interes" aria-label="Permalink to &quot;5.5 Generación de los comprobantes de interés&quot;">​</a></h3><p><code>Guardar_Comprobantes</code> (<code>:1303-1411</code>):</p><ul><li>Agrupa por situación de IVA, cuenta y titular, y genera <strong>un comprobante de venta por cuenta</strong>. Tiene un ítem por factura (&quot;Intereses - {nro}&quot;, subtipo <code>Intereses_cobrados_en_caja</code>); el vendedor sale del parámetro <strong>1008</strong>.</li><li>Forma de pago <code>FormasDePago.Proxima_Facturacion</code>: el interés <strong>no se factura en un comprobante fiscal aparte</strong>, sino que entra como cuota en la próxima factura del servicio.</li><li>Procesa en lotes de 100.</li><li>Según opciones, marca <code>FACTURAS.NOINTERES = 1</code> para no volver a calcular, o <code>COD_FAC = &#39;Punitorio&#39;</code>.</li></ul><p>El informe previo es &quot;Facturacion_InteresAFacturar&quot; (<code>:1260-1301</code>).</p><h3 id="_5-6-precisiones-segunda-pasada" tabindex="-1">5.6 Precisiones (segunda pasada) <a class="header-anchor" href="#_5-6-precisiones-segunda-pasada" aria-label="Permalink to &quot;5.6 Precisiones (segunda pasada)&quot;">​</a></h3><ul><li><p><strong>Rango de fechas según la opción</strong> (<code>Get_Facturas</code>, <code>clsFacturarIntereses.cs:1216-1258</code>). La base son facturas de débito (<code>DEB_CRE = 1</code>), no anuladas y sin <code>NOINTERES</code>. Sobre esa base:</p><ul><li>con <code>CalcularInteresesSoloSobreCargos</code>: VTO1 dentro de <code>[FechaDesde, FechaHasta]</code>;</li><li>con <code>ProcesarPagosEntreFechas</code>: VTO1 anterior a <code>FechaHasta</code>. En la variante AL también entran las facturas saldadas dentro del rango con pagos que incluyen valores (cheques, <code>PLAN_CAJ.VALORES</code>);</li><li>con <code>FacturasImpagas</code>: saldo &gt; 0 y VTO1 dentro del rango;</li><li>sin opciones: saldo &gt; 0, o <code>FECHASALDO ≥ FechaHasta</code>.</li></ul></li><li><p><strong><code>Get_Reporte</code></strong> (<code>:1260-1301</code>): el informe muestra solo los tramos de interés que quedaron <strong>seleccionados</strong> (<code>Interes_DetalleSeleccionado</code>). El operador puede destildar tramos o comprobantes antes de generar, y lo que destilda no se factura. Los totales por comprobante (<code>Dias</code>, <code>Interes_Neto</code>, <code>Interes_IVA</code>) suman solo los tramos seleccionados.</p></li><li><p><strong><code>Guardar_Comprobantes</code></strong> (<code>:1303-1411</code>):</p><ul><li>el número de comprobante se toma una sola vez al inicio y se incrementa en memoria;</li><li>el bloqueo de <code>COMP_VEN</code> se libera (rollback) antes de generar;</li><li>todo se ejecuta al final como un único lote SQL que también actualiza <code>COMPPOS.ULT_NUM</code>.</li></ul><p>Si otro usuario emite el mismo comprobante en paralelo, puede haber numeración duplicada. <strong>[VERIFICAR]</strong> si en la práctica el proceso se corre en exclusividad.</p></li><li><p>El ítem de cada comprobante de interés usa el <strong>neto</strong> del interés (<code>Interes_Neto</code>). El IVA se recalcula al facturar la cuota, con la alícuota del concepto elegido en el proceso.</p></li></ul><h2 id="_6-otros-puntos-de-interes-y-bloqueo" tabindex="-1">6. Otros puntos de interés y bloqueo <a class="header-anchor" href="#_6-otros-puntos-de-interes-y-bloqueo" aria-label="Permalink to &quot;6. Otros puntos de interés y bloqueo&quot;">​</a></h2><ul><li><strong><code>ExisteMoratas(cod_tip, out des_mot)</code></strong> (<code>clsComprobanteFactura.cs:492-508</code>): informa si hay tasas <code>MORATAS</code> para el tipo de factura. Se usa para validar y avisar. Solo considera las tasas específicas del tipo con descripción no vacía (ver §3.3).</li><li><strong><code>Asignar_Bloqueo</code></strong> (<code>clsComprobanteFactura.cs:2532-2590</code>): asigna <code>ID_BLO = causa</code> (o <code>null</code> para desbloquear) por SQL directo, en lotes de 500. <strong>Nunca toca facturas con <code>ID_BLO = -1</code></strong>, que funciona como bloqueo permanente o de sistema. Por cada factura registra <code>HISBLOQ</code> con la causa, la fecha y el <strong>nombre</strong> del usuario (no el alias). <strong>[VERIFICAR]</strong> qué proceso asigna <code>-1</code>.</li><li><strong><code>Asignar_Bloqueo_ConIntereses</code></strong> (<code>clsComprobanteFactura.cs:2592-2635</code>): bloquea facturas (<code>ID_BLO</code>) y genera de inmediato una <strong>factura de intereses</strong> (<code>clsRegistracionCobranza.Generar_Factura_X_Intereses</code>, <code>:1335-1345</code>). Esa factura siempre es factura, aunque el 273 diga nota de débito, y lleva un ítem de producto con IVA incluido. Parámetros relacionados: <strong>2770</strong> (% de interés al desbloquear), <strong>2771</strong> (concepto) y <strong>2984</strong> (tipo de comprobante).</li><li><strong>Caja</strong>: con el parámetro <strong>321</strong> no se permite pagar en forma parcial la deuda notificada; hay que incluir todos los comprobantes de la notificación abierta (<code>clsCobranzaCaja.cs:1660-1669</code>). Con el <strong>324</strong> (más el <strong>462</strong>, que valida contra el VTO4) se obliga a cobrar primero las facturas más antiguas (<code>:1674-1690</code>). <strong>302</strong> y <strong>2453</strong> avisan si el titular está notificado.</li><li><strong>Prepaga</strong>: <code>clsPrepaga.EsExcepcion</code> (<code>ReglasNegocio.Cobranzas/clsPrepaga.cs:1023-1025</code>) no retiene intereses (parámetro <strong>713</strong>) si la cuenta tiene una <code>EXC_MORA</code> con <code>RETENER</code> vigente.</li><li><strong>Otros parámetros</strong>: <strong>3138</strong> (intereses punitorios sobre energía), <strong>3162</strong> (autorización para no cobrar recargo), <strong>2487</strong> (fecha fija de cálculo), <strong>2078</strong> (forma de cobro del interés entre vencimientos), <strong>2562</strong> y <strong>2566</strong> (mostrar interés), <strong>3052</strong> (% diario en reversiones), <strong>339</strong> (comprobante de intereses adelantados). La mayoría no aparece en <code>ReglasNegocio</code>; probablemente se usan en formularios no descompilados.</li></ul><h2 id="_7-gestion-de-mora" tabindex="-1">7. Gestión de mora <a class="header-anchor" href="#_7-gestion-de-mora" aria-label="Permalink to &quot;7. Gestión de mora&quot;">​</a></h2><h3 id="_7-1-estados-y-enums-reglasnegocio-cobranzas-clsgestionmora-cs" tabindex="-1">7.1 Estados y enums (<code>ReglasNegocio.Cobranzas/clsGestionMora.cs</code>) <a class="header-anchor" href="#_7-1-estados-y-enums-reglasnegocio-cobranzas-clsgestionmora-cs" aria-label="Permalink to &quot;7.1 Estados y enums (`ReglasNegocio.Cobranzas/clsGestionMora.cs`)&quot;">​</a></h3><ul><li><code>NOTIFICA.RESUELTA</code> (<code>EstadoResolucion</code>): 0 Inicial (abierta), 1 Pagado, 2 Procesado (pasó a otra instancia), 3 Excluido (baja con causa), 4 En Técnica. El parámetro <strong>2379</strong> define cuándo se usa el estado &quot;En Técnica&quot;.</li><li><code>Calificacion</code>: Sin calificar, Buena, Regular, Mala.</li><li><code>TipoNotificacion</code>: documento impreso, correo, SMS, aviso telefónico o talón de pago.</li><li><code>TipoOperacion</code>: Generar (desde candidatos) o Procesar (instancias siguientes).</li></ul><h3 id="_7-2-seleccion-de-candidatos-reglasnegocio-titulares-clscirculares-cs" tabindex="-1">7.2 Selección de candidatos (<code>ReglasNegocio.Titulares/clsCirculares.cs</code>) <a class="header-anchor" href="#_7-2-seleccion-de-candidatos-reglasnegocio-titulares-clscirculares-cs" aria-label="Permalink to &quot;7.2 Selección de candidatos (`ReglasNegocio.Titulares/clsCirculares.cs`)&quot;">​</a></h3><ol><li><strong>Filtros de cuenta, servicio y deuda</strong> (<code>FiltrosCirculares</code>, <code>:97-294</code>): datos geográficos, servicio, estado y categoría, clase de deuda (financiación o no), tipos de factura, fecha de deuda por emisión o VTO1 con rango, montos y tipo de comprobante (<code>COD_TPFC</code>).</li><li><strong><code>FiltrarDeudas</code></strong> (<code>:1864-1889</code>): comprobantes no anulados con saldo. Opcionalmente excluye créditos y créditos bloqueados (<code>COD_COM 83</code>) y aplica clase, tipo y rango. La opción <code>SinDeuda</code> invierte el criterio.</li><li><strong><code>FiltrarExcepcionesMora</code></strong> (<code>:2312-2351</code>): toma las <code>EXC_MORA</code> con <code>VIGENCIA = &#39;SI&#39;</code>, <code>RECLAMAR</code>, sin cancelación vigente (<code>FEC_VIG</code> nula o pasada) y con <code>FECHA</code> futura o nula. <ul><li>Si <code>FEC_DEUDA</code> es nula, <strong>excluye la cuenta entera</strong>.</li><li>Si no, la excluye cuando tiene deuda con vencimiento anterior a <code>FEC_DEUDA</code>.</li></ul></li><li><strong>Ya notificados</strong> (<code>GetMorososExistentes</code>, <code>:2273-2310</code>): las cuentas con una notificación abierta se informan en <code>MOROSO_TEMPORAL</code> y no se vuelven a cargar. Lo controlan los parámetros <strong>39</strong> (ignorar notificación previa), <strong>384</strong> (ignorar candidato previo), <strong>2467</strong> (considerar solo la instancia inicial) y <strong>3050</strong> (excluir por el mismo tipo de notificación).</li><li><strong><code>Guarda_Candidatos</code></strong> (<code>:2380-2485</code>): crea un <code>NOTIFICA</code> en la instancia <strong>2202</strong> con lote = máximo + 1. Por cada factura guarda una fila en <code>COMPNOTI</code> con el saldo, y en la notificación <code>DEUDA</code> (suma de saldos) y <code>DEUDA_AC</code> (deuda con intereses en modo NoDiferir). Solo inserta la notificación si <code>DEUDA &gt; 0</code>.</li></ol><h3 id="_7-3-avance-de-instancias" tabindex="-1">7.3 Avance de instancias <a class="header-anchor" href="#_7-3-avance-de-instancias" aria-label="Permalink to &quot;7.3 Avance de instancias&quot;">​</a></h3><p><code>clsGestionMora.Get_Notificaciones(Filtros)</code> (<code>:526-604</code>):</p><ul><li>En modo Generar toma las notificaciones de la instancia de candidatos; en modo Procesar, las de las demás instancias.</li><li>En ambos casos solo considera las notificaciones abiertas.</li><li>Filtros: vencidas al (<code>VTO_CIR</code>), fecha, lote, cuenta, servicio, tipo de factura, barrio, localidad, empresa postal, deuda anterior a una fecha (máximo VTO4), deuda mayor a, cantidad mínima de comprobantes, clase, entregadas y con o sin promesa.</li><li><code>ValidarNotificaciones</code> (<code>:2374-2383</code>, parámetro <strong>53</strong>) avisa si la deuda cambió.</li></ul><p><code>Get_Notificaciones_Mora</code> (<code>:487-524</code>) es otra vista para el tratamiento de morosos. Toma notificaciones abiertas con <code>VTO_CIR</code> vencido y sin promesa vigente, y permite filtrar por pagos parciales y cantidad de pagados.</p><p><code>Guardar_Notificaciones(DatosNotificacion)</code> (<code>:975-1247</code>) pasa las notificaciones a la instancia destino:</p><ol><li><strong>Costo de envío</strong> (opcional): comprobante de venta con el concepto <strong>295</strong>. El importe sale de la plantilla o del parámetro <strong>296</strong>, y el comprobante por defecto de la operación <code>Gestion_de_Mora</code>.</li><li><strong>Nueva notificación</strong> con nuevo lote, <code>COD_INS</code> destino, <code>VTO_CIR</code>, plantilla (<code>COD_PLA</code>) y <code>RECIBIO</code> automático según configuración (<strong>2206</strong>; <strong>2279</strong> marca todas como entregadas).</li><li><strong>Comprobantes</strong> (<code>COMPNOTI</code>): los impagos de la notificación anterior o, con <code>IncluirDeudaVencida</code>, toda la deuda vencida a la fecha. <code>DEUDA_AC</code> se recalcula con intereses.</li><li><strong>Nota en la cuenta</strong> (<code>NOTA_SUM</code>): &quot;Notificación de Mora&quot;.</li><li><strong>Notificación anterior</strong>: queda en 2 (Procesado) si todavía hay deuda, o en 1 (Pagado) si no.</li><li><strong>Bloqueo</strong> (opcional): pone <code>ID_BLO = causa</code> en las facturas y registra <code>HISBLOQ</code>. El comprobante de deuda puede ser por titular o por cuenta (<code>Guardar_Comprobante</code>, <code>:1249-1435</code>; parámetros <strong>2304</strong> y <strong>2305</strong>).</li></ol><p>Acciones sobre las notificaciones:</p><ul><li><code>Set_Entrega</code> (<code>:867-884</code>): con la entrega, <code>VTO_CIR = hoy + parámetro 2205 días</code>. El plazo corre desde la entrega. Solo <strong>extiende</strong> el vencimiento: si <code>VTO_CIR</code> ya era posterior, lo deja. Desmarcar la entrega no revierte el vencimiento.</li><li><code>Set_PromesaPago</code> (<code>:886-893</code>), <code>Set_Baja</code> (<code>:895-904</code>, <code>RESUELTA = 3</code> con causa) y <code>Set_Calificacion</code> (<code>:906-913</code>).</li><li>La bitácora queda en <code>OBSERVA2</code> con el formato <code>fecha¦¦usuario¦¦proceso¦¦obs«»</code> (<code>:2364-2372</code>). El informe de promesas la parsea.</li><li><code>Cerrar_Notificaciones</code> (<code>:1502-1540</code>): nota &quot;Notificación Cerrada&quot;, con bloqueo de caja opcional.</li><li><code>Anular_Grupo</code> (<code>:952-973</code>): deshace un lote y reabre el anterior. <code>Eliminar_Notificaciones</code> (<code>:1542-1569</code>).</li><li><code>Restablecer_Notificaciones</code> (<code>:2063-2081</code>): <strong>borra todo</strong> <code>NOTIFICA</code> y <code>COMPNOTI</code>.</li><li><strong>Pago</strong>: <code>clsRegistracionCobranza.RegistrarPagoNotificacion</code> (<code>:1141-1170</code>). Si se pagaron todos los comprobantes de una notificación abierta o &quot;En Técnica&quot;, la marca <code>RESUELTA = 1</code> con fecha y usuario.</li></ul><p>Los parámetros <strong>2203</strong> y <strong>2204</strong> identifican la instancia &quot;sensible&quot; (riesgo de corte) y la instancia de <strong>corte</strong>. En el catálogo <code>clsVariables</code> figuran como &quot;Instancia inicial por defecto de la gestión de mora&quot; y &quot;Instancia final por defecto&quot;. El uso como sensible y corte es el que les da la exportación ERSeP. Se usan, por ejemplo, en la exportación para ERSeP (DNU 311/2020), que informa la condición &quot;R/C&quot; o &quot;A&quot; por cuenta (<code>clsCirculares.Exportar_Excel_ERSeP_DNUN_311_2020</code>, <code>:2523</code>, <code>:2607-2636</code>).</p><h3 id="_7-4-tratamiento-de-morosos-corte" tabindex="-1">7.4 Tratamiento de morosos: corte <a class="header-anchor" href="#_7-4-tratamiento-de-morosos-corte" aria-label="Permalink to &quot;7.4 Tratamiento de morosos: corte&quot;">​</a></h3><ul><li><strong><code>Get_ServiciosTratamientoMorosos</code></strong> (<code>clsGestionMora.cs:1571-1723</code>): lista los servicios conectados (<code>CONDICION = 2</code>) de las cuentas notificadas. Da error si ya hay una OT pendiente (<code>COD_EST</code> 1 o 2) de la misma transacción.</li><li><strong><code>Guardar_OT</code></strong> (<code>:1853-1891</code>) despacha según la transacción: <ul><li><strong>3 Desconexión</strong> (<code>Guardar_OT_Desconexion</code>, <code>:1943-1998</code>): <ul><li>Si el servicio requiere técnica: marca <code>BAJA_ADM</code> y crea una OT de desconexión con origen <code>GestionMora</code>, <code>MOROSO = true</code>, <code>GEST_MORA = true</code> y el vínculo a la notificación (<code>CNT_NOT</code>).</li><li>Si no requiere técnica: desconecta directamente el servicio, sus adherentes y beneficiarios.</li><li>Parámetros <strong>2440</strong> y <strong>2531</strong>: retiro de medidor en la desconexión.</li></ul></li><li><strong>7 Cambio de estado</strong> (<code>:2000-2061</code>): por ejemplo, suspensión o restricción, sin corte físico. El parámetro <strong>2458</strong> bloquea la caja.</li><li><strong>Cambio de categoría</strong> (<code>:1917-1941</code>) o reclamo.</li><li>El parámetro <strong>2694</strong> permite generar OT de morosos sin observación.</li></ul></li><li><strong><code>Baja_Servicio</code></strong> (<code>:1437-1500</code>): <code>CONDICION = 3</code>, <code>BAJA_ADM</code>, y OT de desconexión o desconexión directa.</li><li><strong><code>Operacion_NoFacturar</code></strong> (<code>:2083</code>): <code>SERSOC.NOFACTURAR = 1</code>.</li><li>El parámetro <strong>2917</strong> cancela la desconexión pendiente si se cobra, y el <strong>3033</strong> quita la marca de moroso.</li></ul><h3 id="_7-5-reconexion" tabindex="-1">7.5 Reconexión <a class="header-anchor" href="#_7-5-reconexion" aria-label="Permalink to &quot;7.5 Reconexión&quot;">​</a></h3><p><strong>Automática por cobranza</strong> (<code>clsRegistracionCobranza.cs:270-277</code>). Se activa con los parámetros <strong>3112</strong> (reconectar servicios sin técnica), <strong>3106</strong> (generar OT de reconexión) y <strong>2713</strong> (generar y confirmar la OT).</p><ol><li><code>GetServiciosDesconectadosSinDeuda</code> (<code>:338-370</code>) busca servicios con <code>CONDICION = 4</code> (desconectado) cuya baja fue <strong>por mora</strong>: <ul><li>con técnica: OT de desconexión <code>MOROSO</code> desde 15 días antes de <code>FEC_BAJA</code> y sin OT de reconexión pendiente;</li><li>sin técnica: <code>MOROSO</code> y baja en los últimos 15 días.</li></ul></li><li>La deuda que impide reconectar depende de: <ul><li><strong>3147</strong>: 0 = toda la deuda; 1 = la vencida al VTO2; 2 = la vencida al VTO4;</li><li><strong>3113</strong>: solo la deuda del mismo tipo de factura;</li><li><strong>3163</strong>: en su lugar, que no queden notificaciones abiertas con deuda del servicio.</li></ul></li><li><code>ReconectarServicioSinTecnica</code> (<code>:303-336</code>) pone <code>MOROSO = false</code>, <code>CONDICION = 2</code> y <code>FEC_ALTA = hoy</code>.</li><li><code>GenerarConfirmarOrdenTrabajo</code> (<code>:372-470</code>) crea una OT de reconexión (&quot;Reconexión generada automáticamente por cobranza&quot;). Genera el <strong>cargo de reconexión</strong> como comprobante de venta con el concepto de <code>CONEXION</code> (<code>TIPO_CON = 4</code>) del servicio, y con el 2713 confirma la OT.</li></ol><p><strong>Manual y por OT</strong>:</p><ul><li><code>clsSocios.Get_CONEXION</code> / <code>GetQuery_CONEXION</code> (<code>ReglasNegocio.Titulares/clsSocios.cs:471-569</code>) eligen el cargo de reconexión de <code>CONEXION</code> filtrando por servicio, socio activo o no, <strong>moroso o no</strong>, prepago, zona, localidad, categoría, clase, estado y propiedad. Cada concepto puede cobrarse una sola vez (<code>UNA_VEZ</code>), antes (<code>TIPO_CON 6</code>) o después (<code>TIPO_CON 5</code>) de ejecutar la OT.</li><li><strong>Descuento por días sin servicio</strong> (<code>clsTecnica.Generar_DescuentoReconexion</code>, <code>ReglasNegocio.Tecnica/clsTecnica.cs:1599-1700</code>, parámetros <strong>2483</strong> y <strong>2485</strong>): al reconectar servicios de cargo proporcional, acredita los días desconectados del mes o, con el <strong>2661</strong>, debita los días restantes.</li><li>Otros puntos: <code>clsPagosDesconectados.GenerarReconexion</code> (<code>:100-156</code>), <code>clsCobranzaCaja.Get_SersocReconexion</code> (<code>:1872</code>) y <code>clsTecnica.Validar_OrdenTrabajo_Reconexion</code> (<code>:2963</code>). Parámetros <strong>2707</strong>, <strong>2787</strong>, <strong>3116</strong>, <strong>2301</strong>, <strong>388</strong> y <strong>2907</strong> (este último pregunta antes de generar el descuento).</li></ul><h3 id="_7-6-consultas-canales-y-ordenes-de-trabajo-segunda-pasada-clsgestionmora" tabindex="-1">7.6 Consultas, canales y órdenes de trabajo (segunda pasada, <code>clsGestionMora</code>) <a class="header-anchor" href="#_7-6-consultas-canales-y-ordenes-de-trabajo-segunda-pasada-clsgestionmora" aria-label="Permalink to &quot;7.6 Consultas, canales y órdenes de trabajo (segunda pasada, `clsGestionMora`)&quot;">​</a></h3><p><strong>Consultas de notificaciones</strong></p><ul><li><strong><code>GetAll_Notificaciones(cuenta)</code></strong> (<code>clsGestionMora.cs:606-613</code>): historial completo de notificaciones de la cuenta, en cualquier estado. Aplica <code>ValidarNotificaciones</code> (parámetro <strong>53</strong>).</li><li><strong><code>Get_Notificaciones_Especial(instancia, lote, estado)</code></strong> (<code>:615-633</code>): notificaciones de cualquier estado, filtradas por instancia, lote y estado. Alimenta la pantalla &quot;Operaciones Especiales&quot; (Configuración → Tablas de Gestión de Mora), desde donde se eliminan los lotes que impiden anular una financiación (§8.10).</li><li><strong><code>Get_Notificaciones(cuenta)</code></strong> (<code>:635-638</code>): solo las notificaciones de la cuenta con calificación asignada (<code>CALIFICA ≠ 0</code>). Es el historial de comportamiento de pago.</li><li><strong>Proyección común</strong> (<code>Get_Notificaciones(query, …)</code>, privado, <code>:2247-2362</code>): <ul><li><code>DeudaActual</code> es la suma de los saldos actuales de los comprobantes notificados;</li><li>con &quot;deuda actualizada&quot;, <code>DeudaActualizada</code> recalcula <strong>toda</strong> la deuda de la cuenta, con intereses en modo NoDiferir y sin créditos;</li><li>adjunta los servicios conectados o en alta (<code>CONDICION</code> 1 o 2) de la cuenta.</li></ul></li><li><strong><code>ValidarNotificaciones</code></strong> (<code>:2374-2383</code>): con el parámetro 53 activo marca &quot;abonada&quot; si la deuda actual es 0, o &quot;la composición cambió&quot; si difiere de la notificada. Solo avisa, no cambia el estado.</li><li><strong><code>Get_DetalleComprobantes(notificación, actualizada)</code></strong> (<code>:663-698</code>): <ul><li>sin &quot;actualizada&quot;: recalcula cada comprobante de <code>COMPNOTI</code> con NoDiferir. Avisa &quot;abonado&quot; si el total a pagar es 0, o &quot;saldo cambió&quot; si el saldo difiere del notificado;</li><li>con &quot;actualizada&quot;: trae toda la deuda actual de la cuenta y distingue los comprobantes <strong>notificados</strong> de los <strong>nuevos</strong> (deuda posterior a la notificación).</li></ul></li></ul><p><strong>Impresión agrupada y canales</strong></p><ul><li><strong><code>Get_NotificacionesAgrupadasTitular(ids, orden)</code></strong> (<code>:705-865</code>): agrupa las notificaciones por <strong>titular</strong> para imprimir una sola carta. <ul><li>El domicilio, la zona, el sector, el recorrido y la empresa postal del grupo salen de la <strong>cuenta principal</strong> (<code>SUMSOC.PRINCIPAL</code>) o, si no hay, de la de menor número.</li><li>La fecha y el lote del grupo son los mínimos, y la deuda es la suma.</li><li>Orden de impresión: 0 cuenta, 1 titular, 2 deuda, 3 lote, 4 fecha, 5 calle y número, 6 zona/sector/recorrido, 7 empresa postal y luego zona/sector/recorrido.</li></ul></li><li><strong><code>GetDatosCuentaSinMail(cuentas, soloEmailCuenta)</code></strong> (<code>:915-932</code>): antes de notificar por correo, lista las cuentas sin dirección. Por defecto exige que falten <strong>ambos</strong>, <code>SUMSOC.EMAIL</code> y <code>SUMSOC_EXTRAS.CORREO_WEB</code> (el mail del portal); con <code>soloEmailCuenta</code> mira solo <code>EMAIL</code>.</li><li><strong><code>GetDatosPersonasSinNumero(cuentas)</code></strong> (<code>:934-951</code>): para SMS, lista las cuentas sin <code>PERSONAS.FAX</code> y sin <code>SUMSOC.MOVIL</code>. El campo <code>FAX</code> de la persona se usa como celular alternativo. <strong>[VERIFICAR]</strong> que las cooperativas cargan el celular ahí.</li></ul><p><strong>Órdenes de trabajo del tratamiento de morosos</strong></p><ul><li><strong><code>Get_InfoOT(servicios, conexión)</code></strong> (<code>:1725-1851</code>): arma los datos de la OT a partir del <code>SERSOC</code>: medidor, domicilio del servicio, catastro, GPS, categoría y certificado. Si ningún ítem trae servicio (tratamiento a nivel cuenta), usa el domicilio de la cuenta sin medidor ni categoría. En los dos casos vincula cada OT con su notificación (<code>ID_Notifica</code> → <code>TECNICA.CNT_NOT</code>).</li><li><strong>Despacho en <code>Guardar_OT</code></strong> (<code>:1853-1891</code>), con un único bloqueo de la tabla <code>TECNICA</code> para numerar <code>COD_SOL</code>: <ul><li>si se indica una categoría nueva → cambio de categoría;</li><li>transacción 3 → desconexión;</li><li>transacción 7 → cambio de estado;</li><li>transacción 6 (Incidente/Reclamo) o cualquier código que no pertenezca al enum <code>Transaccion</code> (transacciones propias de la cooperativa) → <strong>reclamo</strong>;</li><li>las transacciones 1, 2, 4, 5 y 8 (alta, traslado, cambio de medidor, reconexión, retiro de medidor) <strong>no generan nada</strong>, sin error.</li></ul></li><li><strong><code>Guardar_OT_Reclamo</code></strong> (<code>:1894-1915</code>): OT con origen <code>GestionMora</code> y moroso. Comprobante por defecto de la operación <code>Orden_de_Trabajo</code> con su punto de venta y número. La descripción usa la <strong>observación</strong> técnica y no la descripción recibida (posible error del código). No marca <code>GEST_MORA</code>.</li><li><strong><code>Guardar_OT_CambioCategoria</code></strong> (<code>:1917-1941</code>): igual que el reclamo, con <code>N_COD_CAT</code> = categoría destino, <code>GEST_MORA</code> y <code>MOROSO</code> en verdadero. El cambio efectivo de categoría ocurre al cumplir la OT en Técnica.</li><li><strong><code>Guardar_OT_CambioEstado</code></strong> (<code>:2000-2061</code>): solo toma servicios en <code>CONDICION</code> 1 o 2. <ul><li>Si el servicio requiere técnica: OT de transacción 7 con <code>COD_ESTASER</code> = estado destino. Origen <strong>Titulares</strong> (no <code>GestionMora</code>), con <code>GEST_MORA</code> y <code>MOROSO</code>, vinculada a la notificación de la cuenta.</li><li>Si no requiere técnica: cambia <code>SERSOC.COD_ESTADO</code> en el acto, sin OT ni historial en este método.</li></ul></li></ul><h2 id="_8-financiacion-y-planes-de-pago" tabindex="-1">8. Financiación y planes de pago <a class="header-anchor" href="#_8-financiacion-y-planes-de-pago" aria-label="Permalink to &quot;8. Financiación y planes de pago&quot;">​</a></h2><h3 id="_8-1-planes-plan-cuo-datosplancuotas-cs" tabindex="-1">8.1 Planes (<code>PLAN_CUO</code>, <code>DatosPlanCuotas.cs</code>) <a class="header-anchor" href="#_8-1-planes-plan-cuo-datosplancuotas-cs" aria-label="Permalink to &quot;8.1 Planes (`PLAN_CUO`, `DatosPlanCuotas.cs`)&quot;">​</a></h3><p>Atributos del plan:</p><ul><li>tipo de pago: entrega y cuotas, o cuotas sin entrega;</li><li>período, cantidad, mínimo y máximo de cuotas;</li><li>tasas <code>INT_TEM</code>, <code>INT_TNA</code> y <code>TASA</code>;</li><li>mínimos y máximos de deuda, entrega mínima (opcionalmente sobre el total con IVA);</li><li>tasa de sellado y si la tasa incluye IVA (<code>TASACONIVA</code>);</li><li><strong>quitas</strong> del interés de financiación (<code>QUITA_INTR</code>) y del interés por mora (<code>QUITA_INTM</code>);</li><li>mora particular de las cuotas (<code>MORA_PARTI</code> / <code>REC_DIAMF</code>);</li><li>ajuste por índice (<code>COD_MON_AJUSTE</code>, <code>COD_TAB</code> → <code>INFLACIO</code>);</li><li>no capitalizar el interés por mora (<code>NOCAP_INTMORA</code>).</li></ul><p>Métodos de cálculo (<code>DatosPlan_MetodoCalculo</code>, <code>clsCaidaCuotas.GetCaida</code>, <code>ReglasNegocio.Cobranzas/clsCaidaCuotas.cs:76-239</code>):</p><table tabindex="0"><thead><tr><th>Método</th><th>Cuota</th></tr></thead><tbody><tr><td>Sin interés</td><td>Capital / n</td></tr><tr><td>Interés directo</td><td>Capital / n + (capital financiable × tasa fija por cuota)</td></tr><tr><td>Francés</td><td><code>C × i / (1 − (1+i)^−n)</code></td></tr><tr><td>Alemán</td><td>Amortización constante + interés sobre el saldo</td></tr><tr><td>Americano</td><td>Solo interés; el capital se paga al final</td></tr><tr><td>Cuotas con saldo</td><td>Capital fijo, el saldo se arrastra</td></tr></tbody></table><p>Los vencimientos son el primer vencimiento + período × (k−1) meses. El IVA del interés usa el concepto <strong>607</strong> (financiación) o <strong>2089</strong> (venta); con <code>TASACONIVA</code> el IVA se separa del interés. También calcula IIBB.</p><h3 id="_8-2-armado-de-cuotas-clsformasdepago-337-613" tabindex="-1">8.2 Armado de cuotas (<code>clsFormasDePago</code>, <code>:337-613</code>) <a class="header-anchor" href="#_8-2-armado-de-cuotas-clsformasdepago-337-613" aria-label="Permalink to &quot;8.2 Armado de cuotas (`clsFormasDePago`, `:337-613`)&quot;">​</a></h3><ul><li>La cuota 0 es la entrega.</li><li><code>Distribuir_IntAnterior</code> y <code>Distribuir_IntMora</code> prorratean en las cuotas el interés anterior (de financiaciones previas) y el interés por mora a la fecha. Aplican las quitas (<code>Porc_Devolucion</code>) y el IVA.</li><li>Con <code>NOCAP_INTMORA</code>, el interés por mora no genera interés de financiación.</li></ul><h3 id="_8-3-registro-del-convenio-reglasnegocio-cobranzas-clsfinanciacion-cs" tabindex="-1">8.3 Registro del convenio (<code>ReglasNegocio.Cobranzas/clsFinanciacion.cs</code>) <a class="header-anchor" href="#_8-3-registro-del-convenio-reglasnegocio-cobranzas-clsfinanciacion-cs" aria-label="Permalink to &quot;8.3 Registro del convenio (`ReglasNegocio.Cobranzas/clsFinanciacion.cs`)&quot;">​</a></h3><ul><li><strong><code>RegistrarFinanciacion</code></strong> (<code>:55-113</code>): bloquea los comprobantes refinanciados, cierra las notificaciones (<code>RegistrarPagoNotificacion</code>), graba <code>REC_CON</code> + <code>IT_RECCO</code>, el capital social y la actualización de los comprobantes.</li><li><strong><code>GetRecCon</code></strong> (<code>:115-164</code>): capital (<code>CAP_A_REF</code>), interés anterior (<code>INT_A_REF</code>), interés por mora a la fecha (<code>INT_A_FEC</code>), deuda total, primera cuota, cantidad de cuotas, entrega, sellado y tasas. El texto del convenio sale del parámetro <strong>507</strong> (sin garante) o <strong>214</strong> (con garante).</li><li><strong><code>GetItRecco</code></strong> (<code>:166-194</code>): por factura, el capital, el interés entre vencimientos (<code>INT_23</code>) y el de mora (<code>INT_FT</code>).</li><li><strong><code>RegistrarComprobantes</code></strong> (<code>:197-245</code>), según el tipo de financiación: <ul><li><strong>cuota en factura mensual</strong>: comprobante de venta y cuotas en <code>DEUDAVTA</code>, que la facturación mensual incorpora;</li><li><strong>chequera</strong>: una <code>FACTURA</code> por cuota (<code>CLASE = 1</code>, <code>NRO_REF</code>), más la cuota 0 de entrega o sellado.</li></ul></li><li><strong>Ítems de las cuotas</strong> (<code>GetComprobante</code> <code>:247-319</code>, <code>GetFacturaCuota</code> <code>:329-424</code>): capital <strong>310</strong>, interés por mora <strong>307</strong>, interés anterior <strong>311</strong>, interés de financiación <strong>607</strong> y sellado <strong>676</strong>.</li><li><code>AjustarIVA_Cuotas</code> (<code>:534-656</code>) recalcula el IVA si cambia la situación de IVA.</li><li><strong>Anulación</strong> (<code>AnularFinanciacion</code> / <code>ValidarAnular</code>, <code>:870-1023</code>): no se puede anular si hay cuotas pagas o facturadas, o notificaciones asociadas.</li><li><strong>Otros parámetros</strong>: <strong>671–675</strong>, <strong>735</strong>, <strong>1030</strong>, <strong>2208</strong>, <strong>2252</strong> y <strong>2634</strong> (límites y opciones); <strong>306</strong> y <strong>2299</strong> (forma de registrar las cuotas); <strong>2607</strong> y <strong>2624</strong> (bonificación por adelanto de cuotas).</li><li><strong>Informes</strong> (<code>clsInformes_Financiacion.cs:322-370</code>): financiaciones del período, por plan, comprobantes y conceptos financiados, cuotas de un convenio (todas o a pagar), estado general de cuotas, cuotas facturadas y cuotas adeudadas a una fecha.</li></ul><h3 id="_8-4-datos-del-plan-datosplancuotas-cargardatosplan-segunda-pasada" tabindex="-1">8.4 Datos del plan (<code>DatosPlanCuotas.CargarDatosPlan</code>, segunda pasada) <a class="header-anchor" href="#_8-4-datos-del-plan-datosplancuotas-cargardatosplan-segunda-pasada" aria-label="Permalink to &quot;8.4 Datos del plan (`DatosPlanCuotas.CargarDatosPlan`, segunda pasada)&quot;">​</a></h3><p><code>DatosPlanCuotas.cs:64-110</code> lee <code>PLAN_CUO</code> por código:</p><table tabindex="0"><thead><tr><th>Campo</th><th>Significado</th><th>Regla</th></tr></thead><tbody><tr><td><code>TIP_PAG</code></td><td><code>DatosPlan_TipoPago</code>: 1 entrega y cuotas, 2 cuotas sin entrega</td><td>—</td></tr><tr><td><code>PER_CUO</code></td><td>Meses entre cuotas</td><td>Vencimiento de la cuota k = primer vencimiento + <code>PER_CUO × (k−1)</code> meses</td></tr><tr><td><code>CAN_CUO</code> / <code>MIN_CUO</code> / <code>MAX_CUO</code></td><td>Cuotas sugeridas, mínimas y máximas</td><td><code>MAX_CUO = 0</code> se interpreta como 999 en <code>GetCantidadCuotas</code></td></tr><tr><td><code>TASA</code></td><td><strong>Tasa por período entre cuotas</strong>, la única que usan las fórmulas</td><td>—</td></tr><tr><td><code>INT_TEM</code> / <code>INT_TNA</code></td><td>Tasa efectiva mensual y nominal anual</td><td>Solo informativas: se copian a <code>REC_CON</code> y no intervienen en el cálculo</td></tr><tr><td><code>COD_CAL</code></td><td><code>DatosPlan_MetodoCalculo</code> (1 a 6, ver §8.5)</td><td>—</td></tr><tr><td><code>MIN_VTA</code> / <code>MAX_VTA</code> / <code>MOD_VTA</code></td><td>Importe mínimo y máximo financiable; mínimo para modificar la venta</td><td>Se validan en pantallas no descompiladas</td></tr><tr><td><code>MIN_ENT</code></td><td>% de entrega mínima</td><td>Se trunca a 100</td></tr><tr><td><code>ENTMIN_IVATOTAL</code></td><td>La entrega mínima se mide sobre el total con IVA</td><td>—</td></tr><tr><td><code>TASASELLADO</code></td><td>Sellado por mil</td><td>Se copia a <code>REC_CON.SELLXMIL</code></td></tr><tr><td><code>TASACONIVA</code></td><td>La tasa ya incluye IVA</td><td>El IVA del interés se separa en lugar de sumarse</td></tr><tr><td><code>QUITA_INTR</code> / <code>QUITA_INTM</code></td><td>% de quita del interés anterior y del interés por mora</td><td>—</td></tr><tr><td><code>MORA_PARTI</code> + <code>REC_DIAMF</code></td><td>Recargo diario propio para cuotas impagas del plan</td><td>Se toma solo si <code>MORA_PARTI</code> está activo</td></tr><tr><td><code>COD_MON_AJUSTE</code>, <code>COD_TAB</code>, <code>COD_PRO_INFLACION</code></td><td>Moneda de ajuste, tabla de índices (<code>INFLACIO</code>) y concepto del ajuste</td><td>Ver §8.8</td></tr><tr><td><code>NOCAP_INTMORA</code></td><td>No capitalizar el interés por mora</td><td>—</td></tr><tr><td><code>NRO_CONRE</code> / <code>NRO_CN2</code></td><td>Plantilla del convenio sin y con garante</td><td>Tienen prioridad sobre los parámetros 507 y 214</td></tr></tbody></table><p><code>TieneIndiceAl(fecha)</code> (<code>:112-127</code>) informa si <code>INFLACIO</code> tiene el índice de la tabla del plan para el mes y año de la fecha. Sirve para validar que se pueda ajustar.</p><p><strong>[VERIFICAR]</strong> la unidad de <code>TASA</code> en las bases reales. El código la usa como fracción por período (<code>(1 + TASA)^n</code>). Si una cooperativa la carga como porcentaje, el francés daría cuotas absurdas, así que probablemente la pantalla la convierte.</p><h3 id="_8-5-formulas-de-cada-sistema-de-amortizacion-clscaidacuotas-segunda-pasada" tabindex="-1">8.5 Fórmulas de cada sistema de amortización (<code>clsCaidaCuotas</code>, segunda pasada) <a class="header-anchor" href="#_8-5-formulas-de-cada-sistema-de-amortizacion-clscaidacuotas-segunda-pasada" aria-label="Permalink to &quot;8.5 Fórmulas de cada sistema de amortización (`clsCaidaCuotas`, segunda pasada)&quot;">​</a></h3><p>Notación:</p><ul><li><code>C</code>: capital a financiar (<code>_CapitalFinanciar</code>);</li><li><code>C&#39;</code>: capital sin el interés por mora (<code>_CapitalSinIntMora = C − InteresMora</code>);</li><li><code>n</code>: cantidad de cuotas;</li><li><code>i</code>: <code>PLAN_CUO.TASA</code>.</li></ul><p>Todos los importes se redondean a <strong>5 decimales</strong>, y ningún método ajusta la última cuota por redondeo, salvo &quot;cuotas con saldo&quot; (<code>clsCaidaCuotas.cs:140-239</code>).</p><table tabindex="0"><thead><tr><th>Método (<code>COD_CAL</code>)</th><th>Capital de la cuota k</th><th>Interés de la cuota k</th><th>Archivo:línea</th></tr></thead><tbody><tr><td>1 Sin interés</td><td><code>C / n</code></td><td>0</td><td><code>:140-158</code></td></tr><tr><td>2 Interés directo</td><td><code>C / n</code></td><td>Fijo: <code>(C − ImporteSinInteres) × i</code>. Con <code>NOCAP_INTMORA</code> se usa <code>C&#39;</code> en lugar de <code>C</code></td><td><code>:159-162</code></td></tr><tr><td>3 Francés</td><td><code>cuota − interés_k</code> (+ <code>(C − C&#39;)/n</code> si no capitaliza)</td><td><code>saldo_k × i</code>, con <code>cuota = base / ((1 − (1+i)^−n) / i)</code>, donde base es <code>C</code> o <code>C&#39;</code></td><td><code>:164-187</code></td></tr><tr><td>4 Alemán</td><td><code>base / n</code> (+ <code>(C − C&#39;)/n</code> si no capitaliza)</td><td><code>saldo_k × i</code>; el saldo baja <code>base/n</code> por cuota</td><td><code>:189-207</code></td></tr><tr><td>5 Americano</td><td>0 en las cuotas 1..n−1; <code>C</code> completo en la cuota n</td><td><code>base × i</code> constante</td><td><code>:209-219</code></td></tr><tr><td>6 Cuotas con saldo</td><td><code>ImporteMáximo − IVA embebido</code> en las cuotas 1..n−1; la cuota n absorbe el resto (<code>C − Σ anteriores</code>)</td><td>0</td><td><code>:221-239</code></td></tr></tbody></table><p>Detalles:</p><ul><li><strong>No capitalizar el interés por mora</strong> (<code>NOCAP_INTMORA</code>, parámetro <code>noCapIntMora</code>): el interés de financiación se calcula solo sobre <code>C&#39;</code>. La mora se reparte <strong>en partes iguales</strong> como capital de cada cuota en francés y alemán. En el americano, la cuota final devuelve <code>C</code> completo.</li><li><strong><code>ImporteSinInteres</code></strong>: en el interés directo se resta de la base. <code>clsFormasDePago.GetCuotas</code> lo pasa como <code>−ImporteTotalQuita</code> (<code>clsFormasDePago.cs:395</code>), así que en el directo el interés se calcula sobre el capital <strong>antes</strong> de la quita, mientras que los demás métodos usan el capital ya neto de quita. <strong>[VERIFICAR]</strong> el signo con que la pantalla carga <code>ImporteTotalQuita</code> y si esta asimetría es intencional.</li><li><strong>Cuotas con saldo</strong>: el usuario fija el importe máximo de cuota con IVA. <code>CalcularImporteIva(true, C, IVA, máx)</code> (<code>:241-251</code>) le quita la parte proporcional de IVA (<code>máx × IVA/(C+IVA)</code>) y el resultado es el capital fijo de cada cuota. Si <code>n × capital &gt; C</code>, la última cuota queda negativa: el código no lo controla y depende de que la pantalla calcule <code>n</code> bien.</li><li><strong>IVA e IIBB del interés</strong> (<code>GetCaida</code>, <code>:76-138</code>): se calculan por cuota, salvo que ya venga calculado. <ul><li>El concepto es el <strong>607</strong> (financiación) o el <strong>2089</strong> (interés de comprobante de venta).</li><li>Con <code>TASACONIVA</code>, el interés calculado se toma como importe con IVA y se separa (<code>Calcular_TasasIVA_Total</code>); si no, el IVA se suma.</li><li>La percepción de IVA se incluye solo si <code>IncluirPercepcionIVA</code> (factura en cuotas con intereses).</li><li>Si la cuenta es conocida (<code>CodSum ≠ 0</code>), calcula IIBB (<code>Calcular_IBR</code>, tipo Facturación) y lo guarda en <code>OtrosImpuestos_Interes</code>.</li></ul></li><li><code>ValorCuota = capital + interés + IVA del interés + otros impuestos</code>. El IVA del <strong>capital</strong> no está en <code>clsCaidaCuotas</code>: lo agrega <code>clsFormasDePago</code> (§8.6).</li></ul><h3 id="_8-6-armado-de-cuotas-entrega-quitas-iva-y-sellado-clsformasdepago-getcuotas-segunda-pasada" tabindex="-1">8.6 Armado de cuotas: entrega, quitas, IVA y sellado (<code>clsFormasDePago.GetCuotas</code>, segunda pasada) <a class="header-anchor" href="#_8-6-armado-de-cuotas-entrega-quitas-iva-y-sellado-clsformasdepago-getcuotas-segunda-pasada" aria-label="Permalink to &quot;8.6 Armado de cuotas: entrega, quitas, IVA y sellado (`clsFormasDePago.GetCuotas`, segunda pasada)&quot;">​</a></h3><p><code>clsFormasDePago.cs:316-446</code>:</p><ol><li><strong>Contado o próxima facturación</strong>: una sola cuota (<code>DEUDAVTA</code>) con vencimiento <code>FechaPago</code>, capital = neto, IVA = suma de IVA1 + IVA2 de los ítems y detalle de IVA por alícuota (<code>IVAVTA</code>).</li><li><strong>Plan de pago o factura en cuotas</strong>: <ul><li><strong>Cuota 0 (entrega)</strong>, solo si <code>Entrega + (sellado si IncluirSelladoCuota0) ≠ 0</code>. Vence <strong>hoy</strong>. <ul><li>En plan de pago, el capital es la entrega y su IVA es proporcional: <code>entrega × (Total − Percepción)/Neto − entrega</code>. El <code>IVAVTA</code> se prorratea con las alícuotas del comprobante original.</li><li>En factura en cuotas, la entrega se carga con IVA incluido y como alícuota 4.</li></ul></li><li><strong>Capital a financiar</strong>: <code>C = Neto − Entrega − ImporteTotalQuita</code>. En factura en cuotas con intereses (<code>FACTURA_CT</code>) se parte del total con IVA: <code>Total − Entrega − Quita − quita de mora proporcional a la entrega − IVA de la entrega</code>.</li><li><strong>Cuotas 1..n</strong>: salen de <code>clsCaidaCuotas.GetCaida</code> (§8.5). <ul><li>En plan de pago: <code>IVA_TOT = IVA del interés + IVA proporcional del capital</code>, con el detalle <code>IVAVTA</code> prorrateado sobre <code>capital − quita por cuota</code>.</li><li>En factura en cuotas sin intereses: el capital se guarda con IVA incluido.</li></ul></li><li><strong>Quita de mora sobre la entrega</strong>: si hay entrega y quita de mora (<code>QUITA_INTM</code>), la parte de mora contenida en la entrega se calcula con la proporción <code>(InteresMora + Quita)/Neto</code> y se le aplica el % de quita.</li><li><strong>Quita del 100 %</strong> con entrega 0: la quita total se reparte en partes iguales (<code>|Quita| / n</code>) al calcular el IVA, y la cuota 0 no recibe distribución de intereses.</li></ul></li><li><strong><code>DistribuirInteresEnCuotas</code></strong> (<code>:448-498</code>): el capital de cada cuota (<code>CAP_FIN</code>) se descompone proporcionalmente en capital puro, interés anterior y mora. <ul><li><strong>Interés anterior</strong> (<code>Distribuir_IntAnterior</code>, <code>:500-531</code>): proporción <code>InteresAnterior / (Neto − Quita)</code> sobre el <code>CAP_FIN</code> de la cuota. A esa porción se le aplica la quita <code>QUITA_INTR</code> (<code>Quita_IntFinanciado</code>, con su IVA), se le separa el IVA con el concepto <strong>311</strong>, y el neto queda en <code>IAN_FIN</code>.</li><li><strong>Interés por mora</strong> (<code>Distribuir_IntMora</code>, <code>:580-613</code>): la reclasificación usa la proporción <code>InteresMora / (Neto − Quita)</code>, que incluye la mora arrastrada de financiaciones previas. La <strong>quita</strong> <code>QUITA_INTM</code> se calcula en cambio sobre la proporción de <code>InteresMoraActual</code>, que es solo el recargo calculado hoy. Así, <strong>la quita de mora no alcanza la mora que ya venía refinanciada</strong>. El IVA se separa con el concepto <strong>307</strong> y el neto queda en <code>IAF_FIN</code>.</li><li>El IVA se separa con <code>Calcular_TasasIVA_Total</code>, porque el interés ya estaba dentro del capital con IVA. En modo financiación se descuenta del capital el IVA sin percepción; en ventas, el IVA con percepción.</li><li><code>DistribuirIVA</code> (<code>:533-578</code>) descuenta del detalle <code>IVAVTA</code> del capital lo reclasificado como interés (con tolerancias de 1 a 3 centavos) y agrega filas de IVA marcadas con <code>TIPO_INT</code> (interés anterior o mora).</li><li><strong>Concepto 308 exento</strong>: si el concepto de &quot;cuota en factura mensual&quot; (parámetro <strong>308</strong>) tiene alícuota 4 y es un plan de pago de financiación, el IVA del detalle se pasa a neto exento, y la cuota se factura como exenta con el IVA dentro del neto. <strong>[VERIFICAR]</strong> qué alícuota representa <code>COD_ALI = 4</code> en cada base.</li></ul></li><li><strong>Saldo por cuota</strong>: cada cuota guarda el saldo restante del plan (<code>Saldo</code>), redondeado a 2 decimales.</li></ol><p><strong>Sellado</strong>:</p><ul><li>en chequera, la cuota 0 (o una factura propia si no hay entrega) lleva el ítem del concepto <strong>676</strong> (<code>clsFinanciacion.GetFacturaCuota</code>, <code>:404-407</code>), y el id se guarda en <code>REC_CON.ID_FAC_SELL</code>;</li><li>en cuota en factura mensual, la entrega y el sellado se emiten como <strong>factura inmediata</strong> al guardar el comprobante de venta (<code>clsComprobanteVenta.Guardar</code>, <code>ReglasNegocio.Facturacion/clsComprobanteVenta.cs:569-600</code>), y el id vuelve como <code>Id_Factura_Cuota0</code>;</li><li><code>AgregarSellado</code> (<code>clsFinanciacion.cs:321-327</code>) agrega el ítem solo si el parámetro 676 valida sin error.</li></ul><p>El importe del sellado lo calcula la pantalla (tasa por mil del plan sobre el total), no esta capa. <strong>[VERIFICAR]</strong> la base del sellado en la pantalla de financiación.</p><p><strong>Cantidad de cuotas para un importe de cuota objetivo</strong> (<code>GetCantidadCuotas</code>, <code>:257-290</code>):</p><ol><li>Punto de partida: <code>n₀ = piso((Neto − Entrega) / importe)</code>. <ul><li>Si <code>n₀</code> supera el máximo del plan: aviso &quot;El importe es muy bajo…&quot; y se usa el máximo.</li><li>Si está debajo del mínimo: se usa el mínimo.</li></ul></li><li>Desde <code>n₀</code> hasta el máximo, busca el primer <code>n</code> en el que la cuota más alta, más el IVA de su capital, no supere el importe pedido.</li><li>Si ninguno cumple: aviso &quot;No se pudo determinar la cantidad de Cuotas&quot; y se usa el máximo.</li></ol><p><strong>Otros métodos de <code>clsFormasDePago</code></strong>:</p><ul><li><code>CargarPago</code> (<code>:99-137</code>): reconstruye la forma de pago de un comprobante de venta desde <code>DEUDAVTA</code>. La entrega es la cuota 0 y la fecha de pago es el vencimiento de la cuota 1.</li><li><code>RegistrarPago</code> (lista original, <code>:159-182</code>): regenera cuotas en las que capital, interés, IVA y otros impuestos quedan en <code>CAP_CUO</code>. Si se agregan otros impuestos, los prorratea según el capital de cada cuota (sin la cuota 0).</li><li><code>RegistrarPagoRapido</code> (<code>:196-206</code>): igual que <code>RegistrarPago</code>, con numeración <code>COD_CVC</code> precalculada para procesos masivos.</li><li><code>CalcularImporteIva</code> (<code>:139-152</code>): IVA proporcional del comprobante sobre un importe. Nunca devuelve un valor negativo.</li></ul><h3 id="_8-7-refinanciacion-segunda-pasada" tabindex="-1">8.7 Refinanciación (segunda pasada) <a class="header-anchor" href="#_8-7-refinanciacion-segunda-pasada" aria-label="Permalink to &quot;8.7 Refinanciación (segunda pasada)&quot;">​</a></h3><p>Un convenio puede incluir cuotas impagas de otro convenio (<code>FACTURAS.CLASE = 1</code>). En ese caso <code>GetRecCon</code> y <code>GetComprobante</code> (<code>clsFinanciacion.cs:115-164</code>, <code>:247-319</code>) <strong>no tratan la cuota como capital puro</strong>, sino que la descomponen:</p><ul><li><strong>Capital</strong>: el capital de la cuota (subtipo 24), que va al concepto <strong>310</strong>.</li><li><strong>Interés anterior</strong>: el interés de financiación actual (21) más el anterior (22) de la cuota, que van al concepto <strong>311</strong>. Se arrastran como &quot;interés anterior&quot; y vuelven a generar interés de financiación en el plan nuevo, salvo la quita <code>QUITA_INTR</code>.</li><li><strong>Mora anterior</strong>: el interés por mora contenido en la cuota (23) se suma a la mora nueva (recargo de hoy) en el concepto <strong>307</strong>. El ítem 307 se emite solo si el neto de mora, quita incluida, supera 0,01.</li><li>Las notas de crédito incluidas restan (signo −1).</li><li>En <code>IT_RECCO</code>, cada comprobante guarda: <ul><li>capital (<code>CAP_A_REF</code>: el saldo, o el capital si es cuota);</li><li>recargo (<code>INT_A_REF</code>) y total (<code>TOT_COM</code>);</li><li>para cuotas: capital, interés actual e interés anterior;</li><li>el <strong>interés entre vencimientos</strong> (<code>INT_23</code>) y el <strong>de mora</strong> (<code>INT_FT</code>) por separado, solo si se cobraron intereses;</li><li>el saldo y la <code>FECHASALDO</code> original, que se usan para revertir al anular.</li></ul></li><li>El comprobante de venta usa la operación <code>Plan_Financiacion</code> y no calcula percepción. Si se financia a otra cuenta (<code>CodSumDestino</code>, parámetro <strong>2634</strong>), toma la situación de IVA e IIBB y el titular de la cuenta destino.</li></ul><h3 id="_8-8-ajustes-de-cuota-al-facturarla-indice-cotizacion-y-adelanto-segunda-pasada" tabindex="-1">8.8 Ajustes de cuota al facturarla: índice, cotización y adelanto (segunda pasada) <a class="header-anchor" href="#_8-8-ajustes-de-cuota-al-facturarla-indice-cotizacion-y-adelanto-segunda-pasada" aria-label="Permalink to &quot;8.8 Ajustes de cuota al facturarla: índice, cotización y adelanto (segunda pasada)&quot;">​</a></h3><p>Cuando la facturación mensual incorpora una cuota de <code>DEUDAVTA</code>, <code>ItemsComprobanteCollection.AddRange</code> (<code>ReglasNegocio.Facturacion/ItemsComprobanteCollection.cs:260-399</code>) agrega ajustes:</p><ul><li><strong>Ajuste por índice</strong> (<code>:370-399</code>). Se aplica si el plan tiene tabla de índices (<code>COD_TAB</code>) y concepto de ajuste (<code>COD_PRO_INFLACION</code>). <ul><li>Factor = índice de <strong>hace 2 meses</strong> / índice del <strong>mes anterior a la fecha del comprobante de venta</strong>.</li><li>Si el factor es distinto de 1, agrega un ítem del concepto de ajuste por <code>(capital + interés + IVA de la cuota) × (factor − 1)</code>, que puede ser negativo si el índice baja.</li><li>Si falta alguno de los dos índices, <strong>no ajusta y no avisa</strong>.</li><li>El rezago de 2 meses está fijo en el código. <strong>[VERIFICAR]</strong> con qué índice se usa (IPC, CAC, etc.).</li></ul></li><li><strong>Diferencia de cotización</strong> (<code>:350-369</code>, parámetros <strong>2289</strong> y <strong>2512</strong>). Se aplica si la venta se hizo en otra moneda y tiene concepto de cotización. <ul><li>Agrega <code>(capital + interés) × (cotización de venta actual / cotización original − 1)</code>, con el grupo de facturación del parámetro 2512.</li></ul></li><li><strong>Bonificación por adelanto de cuotas</strong> (<code>:314-341</code>, parámetros <strong>2607</strong> y <strong>2624</strong>). Si la cuota se factura <strong>por adelantado</strong> (<code>clsFacturacionCuotas.AgregarItemsCuotas</code>, <code>ReglasNegocio.Facturacion/clsFacturacionCuotas.cs:376-391</code>): <ul><li>se agrega un ítem negativo igual al <strong>interés de financiación completo</strong> de la cuota, con el mismo IVA;</li><li>el concepto es el 2607 si la cuota viene de una financiación (tiene capital, mora o interés anterior), o el 2624 si es una venta en cuotas;</li><li>si el parámetro correspondiente es 0, no se bonifica.</li></ul></li></ul><h3 id="_8-9-validaciones-y-parametros-de-financiacion-segunda-pasada" tabindex="-1">8.9 Validaciones y parámetros de financiación (segunda pasada) <a class="header-anchor" href="#_8-9-validaciones-y-parametros-de-financiacion-segunda-pasada" aria-label="Permalink to &quot;8.9 Validaciones y parámetros de financiación (segunda pasada)&quot;">​</a></h3><ul><li><p><strong><code>RegistrarFinanciacion</code></strong> (<code>clsFinanciacion.cs:55-113</code>):</p><ul><li>rechaza la operación si el submódulo de <strong>Facturación está cerrado</strong> para hoy;</li><li>rechaza la operación si el capital total es negativo: &quot;No es posible realizar financiaciones con capital menor a 0&quot;. En ese caso devuelve <code>false</code> <strong>sin rollback explícito</strong> de la transacción abierta;</li><li>todo lo demás (lock de comprobantes, cierre de notificaciones, <code>REC_CON</code>, cuotas, capital social, saldado de facturas con <code>NRO_REF</code>) ocurre en una sola transacción.</li></ul></li><li><p><strong>Límites por convenio</strong>:</p><ul><li><code>GetConveniosEnPeriodo</code> (<code>clsFormasDePago.cs:292-303</code>): cuenta los convenios no anulados de la cuenta, dentro del período de control <strong>674–675</strong> si ambas fechas son válidas, o en total si no. La pantalla lo compara contra <strong>671</strong> (máximo de convenios por período).</li><li><code>GetConveniosActivosPorTipo</code> (<code>:305-309</code>): cuotas de chequera vigentes del tipo de cuota, más cuotas mensuales aún no facturadas. Respalda el <strong>735</strong> (no más de una financiación activa del mismo tipo).</li><li><code>GetConveniosInactivosImpagosPorTipo</code> (<code>:311-314</code>): cuotas mensuales ya facturadas, vencidas e impagas del tipo.</li></ul><p>Estos tres métodos solo se llaman desde pantallas no descompiladas. <strong>[VERIFICAR]</strong> los mensajes y si bloquean o solo advierten.</p></li><li><p><strong>Parámetros que solo leen las pantallas</strong> (no aparecen en <code>ReglasNegocio</code>):</p><ul><li><strong>672</strong> y <strong>2208</strong>: mínimo y máximo de comprobantes a financiar;</li><li><strong>673</strong>: importe mínimo de cada cuota;</li><li><strong>2252</strong>: imprimir el convenio automáticamente;</li><li><strong>306</strong>: forma de registrar las cuotas (0 chequera, 1 factura mensual);</li><li><strong>2299</strong>: permitir cambiar esa forma.</li></ul></li><li><p><strong>1030</strong> (&quot;Permite cambiar interés al operador&quot;): en la caja, en modo financiación, hace visible la operación &quot;Cambiar recargo diario&quot; (<code>clsCobranzaCaja.cs:574-577</code>).</p></li><li><p><strong>2471</strong>: tipo de cuota por defecto (<code>GetCuota_X_Defecto</code>, <code>clsFinanciacion.cs:659-668</code>).</p></li><li><p><strong>Vencimientos de las cuotas en chequera</strong> (<code>GetFacturaCuota</code>, <code>:329-424</code>):</p><ul><li>cada cuota es una <code>FACTURA</code> con operación <code>Cuota_Financiacion</code> y <code>VTO1 = VTO2 = VTO3 = VTO4 = FEC_VTO</code> de la cuota. Por eso <strong>no tiene recargo entre vencimientos</strong>: la mora corre desde el único vencimiento;</li><li>la cuota 0 (entrega o sellado) usa el comprobante que corresponde a la situación de IVA y al tipo de cuota, vence hoy y no lleva <code>Financiacion = true</code>;</li><li>no mueve stock, y registra capital social (<code>registrarCapital: true</code>).</li></ul></li></ul><h3 id="_8-10-anulacion-de-convenios-detalle-segunda-pasada" tabindex="-1">8.10 Anulación de convenios (detalle, segunda pasada) <a class="header-anchor" href="#_8-10-anulacion-de-convenios-detalle-segunda-pasada" aria-label="Permalink to &quot;8.10 Anulación de convenios (detalle, segunda pasada)&quot;">​</a></h3><p><code>AnularFinanciacion</code> / <code>ValidarAnular</code> (<code>clsFinanciacion.cs:870-1023</code>):</p><ul><li>Requiere el permiso <code>FinanciacionANULAR</code> y una confirmación del usuario (&quot;no puede revertirse&quot;).</li><li>Validaciones: <ul><li>el convenio debe existir;</li><li>el submódulo <strong>Financiaciones</strong> no debe estar cerrado a la fecha del convenio;</li><li>en <strong>chequera</strong>, ninguna cuota puede tener <code>SALDO ≠ TOTAL1</code> (pagos parciales o totales): &quot;Debe anular primero los pagos&quot;. Si hay una factura de entrega (<code>CLASE = 0</code>, <code>NRO_CUO = 0</code>) no anulada, pide confirmación;</li><li>en <strong>factura mensual</strong>, ninguna cuota puede estar ya facturada (<code>DEUDAVTA.ID_FAC</code>): &quot;Anule primero las facturas&quot;;</li><li>si la factura de sellado tiene pagos: &quot;Debe anular el Recibo de pago de Sellado&quot;;</li><li>si alguna cuota figura en <code>COMPNOTI</code>, se rechaza la anulación y el mensaje enumera los lotes que hay que eliminar en &quot;Operaciones Especiales&quot;.</li></ul></li><li>Efectos: <ol><li>Cada comprobante refinanciado recupera <code>PAGA = &#39;&#39;</code>, <code>SALDO</code> y <code>FECHASALDO</code> originales, y <code>PAGADO</code> se reduce con el signo del comprobante.</li><li>En chequera, las cuotas <code>CLASE = 1</code> se copian a <code>ANUFAC</code>, <code>ANUITEMSFAC</code> y <code>ANUITEMSFAC_EXTRAS</code>, y se <strong>borran</strong> de <code>FACTURAS</code>. La factura de entrega (<code>CLASE = 0</code>) no se borra en este paso. <strong>[VERIFICAR]</strong> si queda viva cuando el usuario confirma.</li><li>En factura mensual, se anula y elimina el comprobante de venta.</li><li>La factura de sellado se anula con <code>clsAnulacionFacturas</code> (sin eliminarla).</li><li>Se <strong>borran físicamente</strong> <code>IT_RECCO</code>, <code>CAPITAL</code> y <code>REC_CON</code>. Por eso el filtro <code>REC_CON.ESTADO ≠ &#39;A&#39;</code> que usan algunos informes parece heredado de una versión anterior.</li></ol></li></ul><h3 id="_8-11-recalcular-cuotas-por-cambio-de-situacion-fiscal-segunda-pasada" tabindex="-1">8.11 Recalcular cuotas por cambio de situación fiscal (segunda pasada) <a class="header-anchor" href="#_8-11-recalcular-cuotas-por-cambio-de-situacion-fiscal-segunda-pasada" aria-label="Permalink to &quot;8.11 Recalcular cuotas por cambio de situación fiscal (segunda pasada)&quot;">​</a></h3><ul><li><p><strong><code>GetCuotas_SitIvaDistinto(desde, hasta, titular)</code></strong> (<code>clsFinanciacion.cs:426-532</code>) busca cuotas de chequera (<code>CLASE = 1</code>, con <code>NRO_REF</code>) emitidas en el rango y <strong>sin ningún pago</strong> que cumplan alguna de estas condiciones:</p><ul><li>la situación de IVA de la cuota difiere de la actual de la cuenta, y una de las dos es la <strong>7</strong> (<strong>[VERIFICAR]</strong> qué situación es la 7 en <code>SITIVA</code>);</li><li>con el parámetro <strong>757</strong> (IIBB RN 01/2017 Córdoba) y algún concepto de interés (307, 311, 607) con alícuota de IIBB: la alícuota de percepción de IIBB de la cuota difiere de la del padrón <code>IIBB_LUA</code> (régimen <code>P</code>) de la cuenta.</li></ul><p>Devuelve una fila por cuenta con el convenio y la cantidad de cuotas.</p></li><li><p><strong><code>AjustarIVA_Cuotas(lista, modo)</code></strong> (<code>:534-656</code>): por cada cuota impaga de esos convenios toma la situación de IVA actual, borra los ítems de impuestos (<code>TIPO = 4</code>) y los regenera.</p><ul><li><strong>Recálculo de cuota</strong>: mantiene los netos y recalcula IVA y percepción con la alícuota nueva. <code>TOTAL1..TOTAL4</code> y <code>SALDO</code> suben o bajan por la diferencia.</li><li><strong>Recálculo de interés</strong>: mantiene el <strong>total</strong> de la cuota. Reajusta el neto de cada ítem con el factor <code>(100 + IVA ant. + perc. ant. + IIBB ant.) / (100 + IVA nuevo + perc. nueva + IIBB nuevo)</code>, aplicando el IIBB solo a conceptos con alícuota de IIBB. No modifica los totales.</li></ul></li></ul><h3 id="_8-12-consultas-e-informes-de-financiacion-segunda-pasada" tabindex="-1">8.12 Consultas e informes de financiación (segunda pasada) <a class="header-anchor" href="#_8-12-consultas-e-informes-de-financiacion-segunda-pasada" aria-label="Permalink to &quot;8.12 Consultas e informes de financiación (segunda pasada)&quot;">​</a></h3><ul><li><strong><code>GetDatosCuotas(nroRef, ref facturas, idFac)</code></strong> (<code>clsFinanciacion.cs:697-752</code>): <ul><li>en chequera, lista las cuotas (sin la 0) con el desglose por subtipo de ítem: 24 capital, 22 interés anterior, 23 mora, 21 financiación, y la suma de su IVA;</li><li>en factura mensual, lista las cuotas de <code>DEUDAVTA</code> con total = capital + interés + IVA.</li></ul></li><li><strong><code>GetReporteCuotas</code></strong> (<code>:806-846</code>): si el convenio es de factura mensual, devuelve la <strong>liquidación de crédito</strong> del comprobante de venta. Si es chequera, devuelve el talonario de cuotas (&quot;Financiacion_Cuotas&quot;, o &quot;_CUOTAS&quot; para una sola cuota). Acepta un id de factura y deduce el convenio.</li><li><strong><code>GetDatosDeudaCuotas</code></strong> (<code>:754-781</code>): para &quot;factura en cuotas&quot; (no convenio), identifica las cuotas hermanas por la misma cuenta, fecha de emisión, <code>TOTAL1</code> y <code>DE_CUO</code>. Es heurístico: dos facturas en cuotas iguales del mismo día se mezclarían.</li><li><strong><code>ModificarGarante</code></strong> (<code>:670-684</code>): cambia <code>REC_CON.COD_GAR</code> sin validar nada. No vuelve a elegir la plantilla del convenio (507 o 214), que se fijó al crearlo.</li><li><strong><code>clsInformes_Financiacion.GetDatosInforme</code></strong> (<code>clsInformes_Financiacion.cs:31-312</code>): <ul><li><code>GetFinanciaciones</code> (<code>:33-53</code>): convenios por fecha, titular, cuenta y plan. &quot;No incluir cancelados&quot; excluye los convenios mensuales sin cuotas pendientes de facturar. En chequera solo excluye los que no tienen ninguna factura, de modo que <strong>un convenio de chequera totalmente pago sigue apareciendo</strong>. <strong>[VERIFICAR]</strong> si es el comportamiento esperado.</li><li><code>GetCuotasFinanciacionFacturadas</code> (<code>:97-118</code>): cuotas mensuales facturadas en el rango, con capital, mora, interés de financiación e interés anterior. La columna rotulada <code>InteresPorM</code> contiene en realidad <code>IAN_FIN</code> (interés anterior).</li><li><code>GetCuotasFinanciacionAdeudadaAFecha</code> (<code>:120-179</code>): deuda de cuotas a una fecha. <ul><li>En chequera: cuotas emitidas hasta la fecha y no saldadas a esa fecha. Adeudado = <code>TOTAL1 −</code> (pagos <code>IT_PAGSO</code> con interés de financiación más importe imputado hasta esa fecha). No filtra cuotas anuladas.</li><li>En factura mensual: cuotas todavía no facturadas a esa fecha, por su importe completo.</li><li>Informa aparte las cuotas anuladas (ítems del concepto 308 cuya cuota ya no existe) y los créditos sobre capital (subtipo 24) emitidos después de la factura de la cuota.</li></ul></li><li><code>GetComprobantes_Financiados</code> (<code>:180-211</code>): detalle por comprobante refinanciado, con signo según débito o crédito y filtro por tipo de cuota.</li><li><code>GetDatosCuotasPagar</code> (<code>:213-234</code>): cuotas de chequera por convenio, cuenta y rango de número de cuota. La impresión exige convenio o cuenta, y valida que existan (&quot;número de contrato / cuenta no válido&quot;, <code>:700-729</code>).</li><li><code>GetDatosCuotas</code> (<code>:236-293</code>): incluye la cuota 0 y marca pagada o no, con la fecha de pago.</li><li><code>GetEstadoCuotas</code> (<code>:295-311</code>): por convenio, <strong>cantidad e importe de cuotas vencidas impagas</strong> (VTO1 &lt; hoy, saldo ≠ 0, no anuladas).</li></ul></li><li><strong><code>clsMovimientoConceptos.GetFinanciacion</code></strong> (<code>ReglasNegocio.Facturacion/clsMovimientoConceptos.cs:2399</code> en adelante): base del informe &quot;Conceptos financiados&quot;. Toma los <code>IT_RECCO</code> de convenios no anulados y los filtra por: <ul><li>cuenta, titular y estado del titular;</li><li>domicilio de la cuenta o del servicio (zona, localidad, referencia, departamento y sector);</li><li>fecha del convenio y punto de venta;</li><li>tipo de facturación (diaria: VTO1 = fecha);</li><li>tipo de cuota.</li></ul></li><li><strong><code>clsCobranzaCaja.Get_Financiacion(nroRef)</code></strong> (<code>ReglasNegocio.Cobranzas/clsCobranzaCaja.cs:1213-1267</code>): el mismo informe de comprobantes financiados, para un solo convenio. La caja lo imprime al registrar la financiación.</li></ul><h3 id="_8-13-caida-o-caducidad-del-plan" tabindex="-1">8.13 Caída o caducidad del plan <a class="header-anchor" href="#_8-13-caida-o-caducidad-del-plan" aria-label="Permalink to &quot;8.13 Caída o caducidad del plan&quot;">​</a></h3><p>En el código descompilado <strong>no hay ningún proceso de caducidad</strong>: ninguna regla da por vencido el plan, reactiva la deuda original ni recalcula el saldo cuando se acumulan cuotas impagas. Las cuotas impagas siguen estos caminos:</p><ul><li>generan mora por sí mismas como cualquier factura, con la tasa general o con <code>MORA_PARTI</code>/<code>REC_DIAMF</code> del plan;</li><li>pueden entrar en la gestión de mora (filtro de clase &quot;financiación&quot; en Circulares);</li><li>se pueden <strong>refinanciar</strong> en un convenio nuevo (§8.7);</li><li>aparecen en el informe &quot;Estado de cuotas&quot; (cantidad de cuotas atrasadas).</li></ul><p><strong>[VERIFICAR]</strong> con las cooperativas si aplican una caducidad manual (por ejemplo, anular el convenio y refinanciar) y con cuántas cuotas impagas.</p><h2 id="_9-prescripcion-de-deuda" tabindex="-1">9. Prescripción de deuda <a class="header-anchor" href="#_9-prescripcion-de-deuda" aria-label="Permalink to &quot;9. Prescripción de deuda&quot;">​</a></h2><ul><li><strong>Informe &quot;Deuda a Prescribir&quot;</strong> (<code>clsInformes_Mora.cs:100</code>, cálculo en <code>:178</code>): el parámetro <strong>104</strong> fija los meses. Lista las facturas con saldo y VTO1 anterior a hoy menos esos meses, agrupadas por cuenta.</li><li><strong><code>clsPrescripcionDeuda.Registrar_PrescripcionDeuda</code></strong> (<code>ReglasNegocio.Cobranzas/clsPrescripcionDeuda.cs:227</code>): por cada comprobante marcado emite un comprobante de signo contrario (crédito para débitos y viceversa) con el concepto elegido, y lo imputa con recibo. La fecha de corte puede ser la emisión o el VTO1. El parámetro <strong>2158</strong> es la cuenta contable de prescripción.</li></ul><h2 id="_10-informes-de-mora-reglasnegocio-cobranzas-clsinformes-mora-cs" tabindex="-1">10. Informes de mora (<code>ReglasNegocio.Cobranzas/clsInformes_Mora.cs</code>) <a class="header-anchor" href="#_10-informes-de-mora-reglasnegocio-cobranzas-clsinformes-mora-cs" aria-label="Permalink to &quot;10. Informes de mora (`ReglasNegocio.Cobranzas/clsInformes_Mora.cs`)&quot;">​</a></h2><p>Grupo &quot;1- Gestión de Mora&quot;:</p><ul><li>Deuda a Prescribir.</li><li>Notificaciones Pendientes (excluye candidatos).</li><li>Titulares Notificados: deuda notificada, actualizada o detalle.</li><li>Excepciones por Mora: <code>EXC_MORA</code> con motivo, vigencia y usuarios.</li><li>Servicios del lote notificado.</li><li>Promesas de Pago (parsea <code>OBSERVA2</code>).</li></ul><p>También:</p><ul><li><code>Get_InformeDeuda</code> (<code>:1097-1156</code>) y <code>Get_TotalesServicio</code> (<code>:1158-1181</code>).</li><li><strong>&quot;Informe de Servicios a Cortar&quot;</strong> (<code>Get_CortarServicio</code>, <code>:1183-1229</code>): lote, cuenta, medidor, <code>MesesDeuda = (hoy − VTO1 más antiguo) / 30</code> y deuda.</li><li>En <code>clsGestionMora</code>: <ul><li><code>Get_InformeExepcionMora</code> (<code>:2102-2169</code>), calculado con DiferirTodo;</li><li>resumen de notificaciones (<code>:2171-2203</code>);</li><li><strong><code>ExportarDopler</code></strong> (<code>:2205-2245</code>): archivo para Doppler (mail marketing) con cuenta, cantidad de comprobantes, deuda, deuda actualizada y mail.</li></ul></li></ul><h2 id="_11-tabla-de-parametros" tabindex="-1">11. Tabla de parámetros <a class="header-anchor" href="#_11-tabla-de-parametros" aria-label="Permalink to &quot;11. Tabla de parámetros&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º</th><th>Tema</th><th>Uso</th></tr></thead><tbody><tr><td>53</td><td>Mora</td><td>Validar notificaciones (deuda cambiada)</td></tr><tr><td>74</td><td>Emisión</td><td>Tipo de interés entre vencimientos (<code>Facturacion_TipoInteresFactura</code>)</td></tr><tr><td>104</td><td>Prescripción</td><td>Meses para prescribir</td></tr><tr><td>273</td><td>Facturación del interés</td><td>Factura (sí) o nota de débito (no)</td></tr><tr><td>295 / 296</td><td>Mora</td><td>Concepto e importe del costo de notificación</td></tr><tr><td>299 / 1002</td><td>Jubilados</td><td>Sin recargo del VTO2 / sin recargo</td></tr><tr><td>302 / 2453</td><td>Caja</td><td>Aviso de titular notificado</td></tr><tr><td>307 / 310 / 311 / 607 / 676</td><td>Financiación</td><td>Conceptos de mora, capital, interés anterior, interés de financiación y sellado</td></tr><tr><td>321</td><td>Caja</td><td>No permitir pago parcial de deuda notificada</td></tr><tr><td>324 / 462</td><td>Caja</td><td>Cobrar primero las facturas antiguas (por VTO1 o VTO4)</td></tr><tr><td>372</td><td>Mora</td><td>Gastos administrativos</td></tr><tr><td>39 / 384 / 2467 / 3050</td><td>Candidatos</td><td>Control de notificaciones y candidatos previos</td></tr><tr><td>486 / 487</td><td>Caja</td><td>Tasa diaria y concepto por valores a fecha</td></tr><tr><td>578</td><td>Interés</td><td>% entre vencimientos (emisión y CAU)</td></tr><tr><td>600</td><td>Interés</td><td>% diario fijo de mora</td></tr><tr><td>606 / 2080</td><td>Interés</td><td>Concepto de interés por mora / entre vencimientos</td></tr><tr><td>608</td><td>Interés</td><td>Redondear el recargo a 1 decimal</td></tr><tr><td>609</td><td>Interés</td><td>Mínimo (por debajo, el recargo es 0)</td></tr><tr><td>621</td><td>Interés</td><td>Contar el interés desde el último vencimiento</td></tr><tr><td>625</td><td>Interés</td><td>Interés sobre créditos</td></tr><tr><td>713</td><td>Prepaga</td><td>Retener intereses</td></tr><tr><td>1008</td><td>Proceso masivo</td><td>Vendedor de los comprobantes de interés</td></tr><tr><td>1011</td><td>Caja</td><td>Modo de diferir</td></tr><tr><td>1056</td><td>Caja</td><td>Agrupar facturas de interés por tipo</td></tr><tr><td>2202 / 2203 / 2204</td><td>Mora</td><td>Instancias de candidatos, sensible y corte</td></tr><tr><td>2205</td><td>Mora</td><td>Días de vencimiento de la notificación desde la entrega</td></tr><tr><td>2206 / 2279</td><td>Mora</td><td>Recepción automática / todas entregadas</td></tr><tr><td>2292</td><td>Proceso masivo</td><td>Variante (1 estándar, 2 CAU, 3 cheques, 4 AL)</td></tr><tr><td>2300</td><td>Interés</td><td>Impuestos excluidos de la base</td></tr><tr><td>2304 / 2305</td><td>Mora</td><td>Comprobante de deuda por notificación</td></tr><tr><td>2356 / 2363</td><td>Interés</td><td>Discriminar el entre vencimientos / proporcional al saldo</td></tr><tr><td>2379</td><td>Mora</td><td>Estado &quot;En Técnica&quot;</td></tr><tr><td>2385</td><td>Caja</td><td>Ocultar comprobantes con VTO2 viejo</td></tr><tr><td>2440 / 2531</td><td>Corte</td><td>Retiro de medidor</td></tr><tr><td>2458</td><td>Corte</td><td>Bloquear caja en OT de cambio de estado</td></tr><tr><td>2483 / 2485 / 2661 / 2907</td><td>Reconexión</td><td>Descuento por días desconectado</td></tr><tr><td>2770 / 2771 / 2984</td><td>Bloqueo</td><td>Interés al desbloquear</td></tr><tr><td>2826</td><td>Interés</td><td>IIBB sobre el entre vencimientos</td></tr><tr><td>2828</td><td>Diferido</td><td>Relacionar la cuota con el servicio</td></tr><tr><td>2917 / 3033</td><td>Corte</td><td>Cancelar desconexión al cobrar / quitar marca de moroso</td></tr><tr><td>3106 / 3112 / 2713</td><td>Reconexión</td><td>Automática: OT / sin técnica / confirmar OT</td></tr><tr><td>3113 / 3147 / 3163</td><td>Reconexión</td><td>Criterio de deuda para reconectar</td></tr><tr><td>3135</td><td>Interés</td><td>Respetar <code>SIN_RECARGO</code> de la cuenta</td></tr><tr><td>3138</td><td>Interés</td><td>Punitorios sobre energía</td></tr><tr><td>3162</td><td>Caja</td><td>Autorización para no cobrar recargo</td></tr><tr><td>3167</td><td>Interés</td><td>Base = conceptos de <code>CONCEPTOS_INT</code></td></tr><tr><td>214 / 507</td><td>Financiación</td><td>Plantilla del convenio con y sin garante (el plan puede sobrescribirla con <code>NRO_CN2</code> / <code>NRO_CONRE</code>)</td></tr><tr><td>306 / 2299</td><td>Financiación</td><td>Forma de registrar las cuotas (0 chequera, 1 factura mensual) / permitir cambiarla (solo pantallas)</td></tr><tr><td>308</td><td>Financiación</td><td>Concepto de cuota en factura mensual; con alícuota 4 la cuota se factura exenta (§8.6)</td></tr><tr><td>671 / 674 / 675</td><td>Financiación</td><td>Máximo de convenios por período y fechas del período de control</td></tr><tr><td>672 / 2208 / 673</td><td>Financiación</td><td>Mínimo y máximo de comprobantes a financiar; importe mínimo de cuota (solo pantallas)</td></tr><tr><td>735</td><td>Financiación</td><td>No más de una financiación activa del mismo tipo por cuenta</td></tr><tr><td>757</td><td>Financiación / IIBB</td><td>Percepción de IIBB RN 01/2017 (Córdoba): habilita el ajuste de cuotas por cambio de alícuota</td></tr><tr><td>1030</td><td>Caja</td><td>Permitir al operador cambiar el recargo diario en modo financiación</td></tr><tr><td>2089</td><td>Ventas</td><td>Concepto de interés de comprobante de venta (cuotas de venta)</td></tr><tr><td>2252</td><td>Financiación</td><td>Imprimir el convenio al generarlo (solo pantallas)</td></tr><tr><td>2289 / 2512</td><td>Ventas</td><td>Concepto y grupo de facturación para la diferencia de cotización de cuotas</td></tr><tr><td>2471</td><td>Financiación</td><td>Tipo de cuota por defecto</td></tr><tr><td>2607 / 2624</td><td>Financiación / Ventas</td><td>Concepto de bonificación del interés por adelanto de cuotas (0 = no bonifica)</td></tr><tr><td>2634</td><td>Financiación</td><td>Permitir imputar la financiación a otra cuenta</td></tr></tbody></table><h2 id="_12-implicancias-para-goodapps" tabindex="-1">12. Implicancias para GoodApps <a class="header-anchor" href="#_12-implicancias-para-goodapps" aria-label="Permalink to &quot;12. Implicancias para GoodApps&quot;">​</a></h2><ol><li><strong>Separar tres motores</strong>: recargo entre vencimientos al emitir, interés por mora al cobrar o consultar, y proceso masivo de interés a facturar. En GoodApps conviene un <strong>único servicio de cálculo de interés</strong> que reciba la factura, la fecha de corte y la política, y que lo usen caja, portal, entes y el proceso masivo. Procoop duplica la lógica (<code>clsCobranzas</code> frente a <code>clsFacturarIntereses</code>), con criterios que no siempre coinciden.</li><li><strong>Política de tasas configurable con prioridad explícita</strong>: tasa diaria fija, tabla de tasas por vigencia (equivalente a <code>MORATAS</code>, con filtros de tipo de factura y categoría) o índice (equivalente a <code>INDICESMORA</code>). Mantener el interés simple diario como regla por defecto y evitar el interés sobre interés (equivalente a <code>NoCalcularInteresAnterior</code>).</li><li><strong>Modelar el diferimiento como opción de primer nivel</strong>: cobrar en el acto (factura o nota de débito), diferir a la próxima factura (cuota pendiente) o diferir solo la mora. Es lo que más diferencia a las cooperativas y debe poder sobrescribirse por ente recaudador.</li><li><strong>Base imponible y fiscalidad del interés</strong>: concepto de interés por tipo de factura, alícuota de IVA según la situación del titular, percepciones, IIBB opcional, impuestos excluidos de la base y tratamiento &quot;IVA incluido&quot; del entre vencimientos. Debe quedar trazable en el comprobante: un ítem por factura de origen y la relación entre comprobantes.</li><li><strong>Gestión de mora como máquina de estados</strong>: lotes por instancia, con candidato → avisos → instancia sensible → corte. Cada transición registra plantilla, canal, costo de envío, vencimiento desde la entrega, promesas, calificación y bitácora estructurada (no un string como <code>OBSERVA2</code>). El cierre automático por pago debe ser transaccional con la cobranza.</li><li><strong>Excepciones de mora con vigencia y alcance</strong> (cuenta entera o deuda anterior a una fecha), separando &quot;no reclamar&quot; de &quot;no retener o cobrar interés&quot;.</li><li><strong>Corte y reconexión integrados con Técnica</strong>: OT con origen &quot;gestión de mora&quot;, desconexión directa para servicios sin técnica, cargo de reconexión por reglas (servicio, moroso, categoría, zona) y reconexión automática al saldar la deuda, con un criterio de deuda configurable. Contemplar también restricciones regulatorias de corte (ERSeP, DNU 311/2020, electrodependientes).</li><li><strong>Planes de pago</strong>: los métodos francés, alemán, americano, directo y sin interés, más quitas de mora e interés, sellado, entrega, ajuste por índice, modalidad cuota en factura o chequera, y convenio imprimible. La refinanciación debe cerrar las notificaciones y bloquear los comprobantes de origen.</li><li><strong>No replicar rarezas</strong>: el 3 % fijo en el código de CAU, el mínimo que anula el recargo en lugar de aplicar un piso, el punitorio CAU sin días, <code>Fijo_Pesos</code> sin IVA, y el &quot;restablecer&quot; que borra todas las notificaciones. Hay que definir con cada cooperativa el comportamiento deseado.</li><li><strong>Migración</strong>: traer <code>MORATAS</code>, <code>MORATAS_CATSER</code>, <code>INDICESMORA</code>, <code>TRAMASREC</code>, <code>CONCEPTOS_INT</code>, <code>DESCUENTO_CAJA</code>, <code>EXC_MORA</code>, <code>INSTANCI</code>, las notificaciones abiertas con sus comprobantes, los convenios vigentes (<code>REC_CON</code>, <code>IT_RECCO</code>, cuotas) y las cuotas de intereses diferidos pendientes (<code>DEUDAVTA</code> con <code>TPCUOTA = 1</code>), para no perder intereses devengados ni el estado de la gestión.</li></ol><h2 id="_13-dudas-abiertas" tabindex="-1">13. Dudas abiertas <a class="header-anchor" href="#_13-dudas-abiertas" aria-label="Permalink to &quot;13. Dudas abiertas&quot;">​</a></h2><ol><li>Las pantallas de gestión de mora, MORATAS, instancias y excepciones están en ensamblados de formularios (Cobranzas, Titulares) que no se descompilaron. No se verificó cómo se eligen la instancia destino, la plantilla ni el costo, ni qué parámetros leen solo esas pantallas (3138, 2770, 2917, 3033, 2487, etc.).</li><li><strong><code>Get_Recargo</code>, impuestos excluidos</strong>: la línea que descuenta los impuestos excluidos cuando hubo pagos parciales divide por <code>Total1 × Saldo</code>. Parece un error; lo esperable sería prorratear <code>× Saldo / Total1</code>. Conviene validarlo con datos reales.</li><li><strong>Mínimo 609</strong>: hay que confirmar con usuarios que la intención es &quot;no cobrar si es menor&quot; y no &quot;cobrar al menos&quot;.</li><li><strong>Índices</strong>: se usa el índice &quot;siguiente o igual&quot; para la fecha base y el &quot;anterior o igual&quot; para la fecha de consulta. ¿Qué índice usan las cooperativas (BCRA, tasa activa BNA)? ¿Cómo se cargan?</li><li><strong>MORATAS</strong>: la tasa es &quot;% diario&quot; (<code>TASA_CASO</code>). Falta confirmar si alguna cooperativa la carga como mensual o anual y la convierte manualmente.</li><li><strong>CAU</strong>: ¿es la Cooperativa de Agua y Urbanización? ¿Sigue vigente el 3 % fijo sobre los cargos 96/97? ¿Qué son esos comprobantes?</li><li><strong>AL</strong>: identificar la cooperativa y por qué necesita los ajustes por pagos y cheques anteriores.</li><li><strong>Proceso masivo frente a caja</strong>: si una cooperativa usa el proceso masivo y además cobra mora en caja, ¿cómo evita el doble cobro? Se sospecha que mediante <code>NOINTERES</code> y <code>COD_FAC = &#39;Punitorio&#39;</code>, pero no se verificó en caja.</li><li><strong>Reconexión automática</strong>: la ventana de 15 días alrededor de <code>FEC_BAJA</code> para identificar bajas por mora está fija en el código. Confirmar si es intencional.</li><li><strong>Cargo de reconexión automática</strong>: la forma de pago del comprobante de venta toma la fecha de hoy. ¿Se factura en la próxima factura o queda como deuda inmediata?</li><li><strong>Estados de mora</strong>: ¿cuántas instancias usan en la práctica las cooperativas objetivo? ¿Se usa el canal SMS o mail desde la gestión de mora o solo la impresión?</li><li><strong>Prescripción</strong>: ¿qué plazo legal aplican (parámetro 104)? ¿Interviene contabilidad con la cuenta 2158 en todas las cooperativas?</li><li><strong>Tramas en cascada</strong>: en <code>Tramas_Importe</code>, VTO3 y VTO4 aplican la trama dos o tres veces con días acumulados (§3.3). ¿Es lo que las cooperativas esperan ver impreso?</li><li><strong>Tasas <code>MORATAS</code> superpuestas</strong>: la validación de carga no detecta superposición entre tasas generales sin categorías (§4.5). Hay que revisar en las bases si hay tramos duplicados que hoy suman interés dos veces.</li><li><strong>Unidad de <code>PLAN_CUO.TASA</code></strong>: el código la usa como fracción por período entre cuotas, y <code>INT_TEM</code>/<code>INT_TNA</code> son solo informativas (§8.4). Confirmar cómo se cargan.</li><li><strong>Quita en el interés directo</strong>: el interés directo se calcula sobre el capital previo a la quita, a diferencia de los otros métodos (§8.5).</li><li><strong>Caducidad de planes</strong>: no existe en el código (§8.13). ¿Cómo la manejan operativamente?</li><li><strong>Anulación en chequera</strong>: la factura de entrega (cuota 0) no se borra con el convenio (§8.10). ¿Queda como deuda?</li></ol><h2 id="_14-revision-de-metodos-segunda-pasada" tabindex="-1">14. Revisión de métodos (segunda pasada) <a class="header-anchor" href="#_14-revision-de-metodos-segunda-pasada" aria-label="Permalink to &quot;14. Revisión de métodos (segunda pasada)&quot;">​</a></h2><p><strong>Métodos sin regla de negocio</strong> (revisados; consultas, wrappers o armado de informes):</p><ul><li><code>clsCobranzaCaja.Get_PLAN_CAJ</code>;</li><li><code>clsFinanciacion.ObtenerGarante</code>, <code>GetDatosCuotas(nroRef)</code> (wrapper), <code>GetFacturasFinanciadas</code>, <code>GetReporteDeudaCuotas</code>;</li><li><code>clsFormasDePago.GetDatosPlan</code>;</li><li><code>clsGestionMora.Get_ExcepcionesMoraDatasource</code>, <code>Get_ResumenNotificaciones</code> (dos sobrecargas), <code>Get_Notificaciones(lista de ids)</code> (lectura en lotes de 2000);</li><li><code>clsInformes_Financiacion.GetFinanciacionesPeriodo</code>, <code>GetListados</code>, <code>GetFiltros</code>;</li><li><code>clsInformes_Mora.GetListados</code> (los seis informes de §10), <code>GetFiltros</code>, <code>Imprimir</code> y los <code>LoadFiltro_*</code>/<code>Imprimir_*</code> (solo armado de filtros y títulos; el filtro de prescripción toma su fecha por defecto de hoy menos el parámetro 104).</li></ul><p><strong>Fuera de alcance</strong>: <code>clsSCotiz.GetDetalles_PlanillAdjudicacion</code> (<code>ReglasNegocio.Facturacion/clsSCotiz.cs:1242</code>) es parte de <strong>Compras</strong>, no de mora: adjudica por producto la cotización de menor costo e incluye a todos los proveedores empatados. Corresponde documentarlo en el documento de compras.</p><p><strong>Formularios de Configuración</strong>: se buscaron en <code>binarios/decompilado/Configuracion/</code> (Configuracion, Configuracion.Forms, .Abms, .Funcionalidades, .Herramientas) pantallas que usen <code>MORATAS</code>, <code>MORATAS_CATSER</code>, <code>INSTANCI</code>, <code>EXC_MORA</code>, <code>PLAN_CUO</code>, <code>TIP_FIN</code>, <code>INDICESMORA</code>, <code>TABMORA</code>, <code>TRAMASREC</code>, <code>DESCUENTO_CAJA</code> o <code>CONCEPTOS_INT</code>, o los parámetros de mora y financiación. <strong>No hay ninguna</strong>. Los ABM de tasas de mora, instancias, excepciones y planes están en ensamblados no descompilados, igual que las pantallas de gestión de mora (§13, punto 1). Lo único relacionado es:</p><ul><li><code>abm_Servicio_Categorias</code> (<code>Configuracion.Forms/abm_Servicio_Categorias.cs:541-586, 859, 966</code>): asocia una tabla de ajuste (<code>TABINFL</code>, <code>CATE_SER_EXTRAS.COD_TAB</code>) a la categoría de servicio. Es ajuste tarifario, no mora.</li><li><code>abm_conceptos_tasas</code> (<code>Configuracion/abm_conceptos_tasas.cs:31-36</code>): es de Compras (<code>CON_TASAS</code>), no tiene relación con tasas de interés.</li></ul><p>Las validaciones de negocio disponibles para la carga de tasas y descuentos de caja son las de §4.5.</p>',168)])])}const m=o(d,[["render",n]]);export{g as __pageData,m as default};
